from __future__ import annotations

from typing import Any

FONTI_GUIDE_20261106: dict[str, dict[str, Any]] = {
    "cc_1159bis": {"norma": "art. 1159-bis c.c.", "titolo": "Usucapione speciale per la piccola proprieta' rurale", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art1159bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "La proprieta' dei fondi rustici con annessi fabbricati situati in comuni classificati montani dalla legge si acquista in virtu' del possesso continuato per quindici anni."},
    "cc_1170": {"norma": "art. 1170 c.c.", "titolo": "Azione di manutenzione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art1170", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Chi e' stato molestato nel possesso di un immobile, di un diritto reale sopra un immobile o di un'universalita' di mobili puo', entro l'anno dalla turbativa, chiedere la manutenzione del possesso medesimo. L'azione e' data se il possesso dura da oltre un anno, continuo e non interrotto, e non e' stato acquistato violentemente o clandestinamente."},
    "cc_1453": {"norma": "art. 1453 c.c.", "titolo": "Risolubilita' del contratto per inadempimento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art1453", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Nei contratti con prestazioni corrispettive, quando uno dei contraenti non adempie le sue obbligazioni, l'altro puo' a sua scelta chiedere l'adempimento o la risoluzione del contratto, salvo, in ogni caso, il risarcimento del danno."},
    "cc_1455": {"norma": "art. 1455 c.c.", "titolo": "Importanza dell'inadempimento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art1455", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il contratto non si puo' risolvere se l'inadempimento di una delle parti ha scarsa importanza, avuto riguardo all'interesse dell'altra."},
    "cc_2043": {"norma": "art. 2043 c.c.", "titolo": "Risarcimento per fatto illecito", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2043", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Qualunque fatto doloso o colposo, che cagiona ad altri un danno ingiusto, obbliga colui che ha commesso il fatto a risarcire il danno."},
    "cc_2059": {"norma": "art. 2059 c.c.", "titolo": "Danni non patrimoniali", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2059", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il danno non patrimoniale deve essere risarcito solo nei casi determinati dalla legge."},
    "cc_2087": {"norma": "art. 2087 c.c.", "titolo": "Tutela delle condizioni di lavoro", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2087", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "L'imprenditore e' tenuto ad adottare nell'esercizio dell'impresa le misure che, secondo la particolarita' del lavoro, l'esperienza e la tecnica, sono necessarie a tutelare l'integrita' fisica e la personalita' morale dei prestatori di lavoro."},
    "cc_2096": {"norma": "art. 2096 c.c.", "titolo": "Assunzione in prova", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2096", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Salvo diversa disposizione delle norme corporative, l'assunzione del prestatore di lavoro per un periodo di prova deve risultare da atto scritto. L'imprenditore e il prestatore di lavoro sono rispettivamente tenuti a consentire e a fare l'esperimento che forma oggetto del patto di prova. Durante il periodo di prova ciascuna delle parti puo' recedere dal contratto, senza obbligo di preavviso o d'indennita'."},
    "cc_2112": {"norma": "art. 2112 c.c.", "titolo": "Mantenimento dei diritti dei lavoratori in caso di trasferimento d'azienda", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2112", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "In caso di trasferimento d'azienda, il rapporto di lavoro continua con il cessionario ed il lavoratore conserva tutti i diritti che ne derivano. Il cedente ed il cessionario sono obbligati, in solido, per tutti i crediti che il lavoratore aveva al tempo del trasferimento."},
    "cc_2118": {"norma": "art. 2118 c.c.", "titolo": "Recesso dal contratto a tempo indeterminato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2118", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Ciascuno dei contraenti puo' recedere dal contratto di lavoro a tempo indeterminato, dando il preavviso nel termine e nei modi stabiliti dalle norme corporative, dagli usi o secondo equita'. In mancanza di preavviso, il recedente e' tenuto verso l'altra parte a un'indennita' equivalente all'importo della retribuzione che sarebbe spettata per il periodo di preavviso."},
    "cc_2119": {"norma": "art. 2119 c.c.", "titolo": "Recesso per giusta causa", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2119", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Ciascuno dei contraenti puo' recedere dal contratto prima della scadenza del termine, se il contratto e' a tempo determinato, o senza preavviso, se il contratto e' a tempo indeterminato, qualora si verifichi una causa che non consenta la prosecuzione, anche provvisoria, del rapporto."},
    "cc_2275": {"norma": "art. 2275 c.c.", "titolo": "Liquidatori", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2275", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Se il contratto non prevede il modo di liquidare il patrimonio sociale e i soci non sono d'accordo nel determinarlo, la liquidazione e' fatta da uno o piu' liquidatori, nominati con il consenso di tutti i soci o, in caso di disaccordo, dal presidente del tribunale. I liquidatori possono essere revocati per volonta' di tutti i soci e in ogni caso dal tribunale per giusta causa su domanda di uno o piu' soci."},
    "cc_2367": {"norma": "art. 2367 c.c.", "titolo": "Convocazione su richiesta di soci", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2367", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Gli amministratori o il consiglio di gestione devono convocare senza ritardo l'assemblea, quando ne e' fatta domanda da tanti soci che rappresentino almeno il ventesimo del capitale sociale nelle societa' che fanno ricorso al mercato del capitale di rischio e il decimo del capitale sociale nelle altre o la minore percentuale prevista nello statuto, e nella domanda sono indicati gli argomenti da trattare."},
    "cc_2377": {"norma": "art. 2377 c.c.", "titolo": "Annullabilita' delle deliberazioni", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2377", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Le deliberazioni dell'assemblea, prese in conformita' della legge e dell'atto sostitutivo, vincolano tutti i soci, ancorche' non intervenuti o dissenzienti . Le deliberazioni che non sono prese in conformita' della legge o dello statuto possono essere impugnate dai soci assenti, dissenzienti od astenuti, dagli amministratori, dal consiglio di sorveglianza e dal collegio sindacale."},
    "cc_2378": {"norma": "art. 2378 c.c.", "titolo": "Procedimento d'impugnazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2378", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "L'impugnazione e' proposta con atto di citazione davanti al tribunale del luogo dove la societa' ha sede. Il socio o i soci opponenti devono dimostrarsi possessori al tempo dell'impugnazione del numero delle azioni previsto dal terzo comma dell'articolo 2377."},
    "cc_2395": {"norma": "art. 2395 c.c.", "titolo": "Azione individuale del socio e del terzo", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2395", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Le disposizioni dei precedenti articoli non pregiudicano il diritto al risarcimento del danno spettante al singolo socio o al terzo che sono stati direttamente danneggiati da atti colposi o dolosi degli amministratori. L'azione puo' essere esercitata entro cinque anni dal compimento dell'atto che ha pregiudicato il socio o il terzo."},
    "cc_2396quater": {"norma": "art. 2396-quater c.c.", "titolo": "Denunzia al tribunale", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2396quater", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Se vi e' fondato sospetto che gli amministratori, in violazione dei loro doveri, abbiano compiuto gravi irregolarita' nella gestione che possono arrecare danno alla societa' o a una o piu' societa' controllate, i soci che rappresentano il decimo del capitale sociale o, nelle societa' che fanno ricorso al mercato del capitale di rischio, il ventesimo del capitale sociale possono denunziare i fatti al tribunale con […]"},
    "cc_243bis": {"norma": "art. 243-bis c.c.", "titolo": "Articolo 243-bis", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art243bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Disconoscimento di paternita' L'azione di disconoscimento di paternita' del figlio nato nel matrimonio puo' essere esercitata dal marito, dalla madre e dal figlio medesimo. Chi esercita l'azione e' ammesso a provare che non sussiste rapporto di filiazione tra il figlio e il presunto padre. La sola dichiarazione della madre non esclude la paternita'."},
    "cc_2476": {"norma": "art. 2476 c.c.", "titolo": "Responsabilita' degli amministratori e controllo dei soci", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2476", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Gli amministratori sono solidalmente responsabili verso la societa' dei danni derivanti dall'inosservanza dei doveri ad essi imposti dalla legge e dall'atto costitutivo per l'amministrazione della societa'. Tuttavia la responsabilita' non si estende a quelli che dimostrino di essere esenti da colpa e, essendo a cognizione che l'atto si stava per compiere, abbiano fatto constare del proprio dissenso."},
    "cc_2487": {"norma": "art. 2487 c.c.", "titolo": "Nomina e revoca dei liquidatori; criteri di svolgimento della liquidazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2487", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Salvo che nei casi previsti dai numeri 2), 4) e 6) del primo comma dell'articolo 2484 non abbia gia' provveduto l'assemblea e salvo che l'atto costitutivo o lo statuto non dispongano in materia, gli amministratori, contestualmente all'accertamento della causa di scioglimento, debbono convocare l'assemblea dei soci perche' deliberi, con le maggioranze previste per le modificazioni dell'atto costitutivo o dello […]"},
    "cc_2489": {"norma": "art. 2489 c.c.", "titolo": "Poteri, obblighi e responsabilita' dei liquidatori", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2489", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Salvo diversa disposizione statutaria, ovvero adottata in sede di nomina, i liquidatori hanno il potere di compiere tutti gli atti utili per la liquidazione della societa'."},
    "cc_269": {"norma": "art. 269 c.c.", "titolo": "Dichiarazione giudiziale di paternita' e maternita'", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art269", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "La paternita' e la maternita' possono essere giudizialmente dichiarate nei casi in cui il riconoscimento e' ammesso. La prova della paternita' e della maternita' puo' essere data con ogni mezzo. La maternita' e' dimostrata provando la identita' di colui che si pretende essere figlio e di colui che fu partorito dalla donna, la quale si assume essere madre."},
    "cc_270": {"norma": "art. 270 c.c.", "titolo": "Legittimazione attiva e termine", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art270", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "L'azione per ottenere che sia dichiarata giudizialmente la paternita' o la maternita' e' imprescrittibile riguardo al figlio. Se il figlio muore prima di avere iniziato l'azione, questa puo' essere promossa dai discendenti , entro due anni dalla morte. L'azione promossa dal figlio, se egli muore, puo' essere proseguita dai discendenti legittimi, legittimati o naturali riconosciuti. Si applica l'articolo 245."},
    "cc_273": {"norma": "art. 273 c.c.", "titolo": "Azione nell'interesse del minore o dell'interdetto", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art273", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "L'azione per ottenere che sia giudizialmente dichiarata la paternita' o la maternita' puo' essere promossa, nell'interesse del minore, dal genitore che esercita la responsabilita' genitoriale prevista dall'articolo 316 o dal tutore. Il tutore pero' deve chiedere l'autorizzazione del giudice, il quale puo' anche nominare un curatore speciale."},
    "cc_2947": {"norma": "art. 2947 c.c.", "titolo": "Prescrizione del diritto al risarcimento del danno", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art2947", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il diritto al risarcimento del danno derivante da fatto illecito si prescrive in cinque anni dal giorno in cui il fatto si e' verificato. Per il risarcimento del danno prodotto dalla circolazione dei veicoli di ogni specie il diritto si prescrive in due anni."},
    "cc_337ter": {"norma": "art. 337-ter c.c.", "titolo": "Articolo 337-ter", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art337ter", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Provvedimenti riguardo ai figli Il figlio minore ha il diritto di mantenere un rapporto equilibrato e continuativo con ciascuno dei genitori, di ricevere cura, educazione, istruzione e assistenza morale da entrambi e di conservare rapporti significativi con gli ascendenti e con i parenti di ciascun ramo genitoriale."},
    "cc_374": {"norma": "art. 374 c.c.", "titolo": "Autorizzazione del giudice tutelare", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art374", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il tutore non puo' senza l'autorizzazione del giudice tutelare: 1) acquistare beni, eccettuati i mobili necessari per l'uso del minore, per l'economia domestica e per l'amministrazione del patrimonio; 2) alienare beni, eccettuati i frutti e i mobili soggetti a facile deterioramento; 3) riscuotere capitali; 4) costituire pegni o ipoteche, ovvero consentire alla cancellazione di ipoteche o allo svincolo di pegni; 5) […]"},
    "cc_415": {"norma": "art. 415 c.c.", "titolo": "Persone che possono essere inabilitate", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art415", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il maggiore di eta' infermo di mente, lo stato del quale non e' talmente grave da far luogo all'interdizione, puo' essere inabilitato. Possono anche essere inabilitati coloro che, per prodigalita' o per abuso abituale di bevande alcooliche o di stupefacenti, espongono se' o la loro famiglia a gravi pregiudizi economici."},
    "cc_417": {"norma": "art. 417 c.c.", "titolo": "Istanza d'interdizione o d'inabilitazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;262~art417", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "L'interdizione e l'inabilitazione possono essere promosse dalle persone indicate negli articoli 414 e 415, dal coniuge, dalla persona stabilmente convivente, dai parenti entro il quarto grado, dagli affini entro il secondo grado, dal tutore o curatore ovvero dal pubblico ministero."},
    "ccii_art206": {"norma": "art. 206 CCII", "titolo": "Impugnazioni", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2019-01-12;14~art206", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Contro il decreto che rende esecutivo lo stato passivo puo' essere proposta opposizione, impugnazione dei crediti ammessi o revocazione. 2. Con l'opposizione il creditore o il titolare di diritti su beni mobili o immobili contestano che la propria domanda sia stata accolta in parte o sia stata respinta. L'opposizione e' proposta nei confronti del curatore. 3."},
    "ccii_art207": {"norma": "art. 207 CCII", "titolo": "Procedimento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2019-01-12;14~art207", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le impugnazioni di cui all'articolo 206 si propongono con ricorso entro il termine perentorio di trenta giorni dalla comunicazione di cui all'articolo 205 ovvero, nel caso di revocazione, dalla scoperta della falsita', del dolo, dell'errore o del documento di cui all'articolo 206, comma 5. 2."},
    "com_art1352": {"norma": "art. 1352 D.Lgs. 66/2010", "titolo": "Illecito disciplinare", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-03-15;66~art1352", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Costituisce illecito disciplinare ogni violazione dei doveri del servizio e della disciplina militare sanciti dal presente codice, dal regolamento, o conseguenti all'emanazione di un ordine. 2. La violazione dei doveri indicati nel comma 1 comporta sanzioni disciplinari di stato o sanzioni disciplinari di corpo."},
    "com_art1357": {"norma": "art. 1357 D.Lgs. 66/2010", "titolo": "Sanzioni disciplinari di stato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-03-15;66~art1357", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le sanzioni disciplinari di stato sono: a) la sospensione disciplinare dall'impiego per un periodo da uno a dodici mesi; b) la sospensione disciplinare dalle funzioni del grado per un periodo da uno a dodici mesi; c) la cessazione dalla ferma o dalla rafferma per grave mancanza disciplinare o grave inadempienza ai doveri del militare; d) la perdita del grado per rimozione."},
    "com_art1363": {"norma": "art. 1363 D.Lgs. 66/2010", "titolo": "Organo sovraordinato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-03-15;66~art1363", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. L'organo sovraordinato di cui all'articolo 1 del decreto del Presidente della Repubblica 24 novembre 1971, n. 1199, è rappresentato dall'organo gerarchicamente superiore a quello che ha emesso il provvedimento. 2."},
    "com_art1365": {"norma": "art. 1365 D.Lgs. 66/2010", "titolo": "Istanza di riesame delle sanzioni disciplinari di corpo", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-03-15;66~art1365", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Ogni militare può presentare, in qualunque tempo, istanza scritta tendente a ottenere il riesame della sanzione disciplinare inflittagli, se sopravvengono nuove prove tali da far ritenere applicabile una sanzione minore o dichiarare il proscioglimento dall'addebito. 2."},
    "com_art1366": {"norma": "art. 1366 D.Lgs. 66/2010", "titolo": "Ricorso gerarchico avverso le sanzioni disciplinari di corpo", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-03-15;66~art1366", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il superiore, per il cui tramite va proposto il ricorso gerarchico, deve inoltrarlo sollecitamente senza pareri o commenti all'autorità gerarchica immediatamente superiore a quella che ha inflitto la sanzione di corpo."},
    "com_art1370": {"norma": "art. 1370 D.Lgs. 66/2010", "titolo": "Contestazione degli addebiti e diritto di difesa", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-03-15;66~art1370", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Nessuna sanzione disciplinare può essere inflitta senza contestazione degli addebiti e senza che sono state acquisite e vagliate le giustificazioni addotte dal militare interessato. 2. Il militare inquisito è assistito da un difensore da lui scelto fra militari in servizio, anche non appartenenti al medesimo ente o Forza armata nella quale egli presta servizio o, in mancanza, designato d'ufficio."},
    "com_art1392": {"norma": "art. 1392 D.Lgs. 66/2010", "titolo": "Termini del procedimento disciplinare di stato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-03-15;66~art1392", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il procedimento disciplinare di stato a seguito di giudizio penale, salvo il caso in cui l'amministrazione abbia già proceduto disciplinarmente ai sensi dell'articolo 1393, comma 1, deve essere instaurato con la contestazione degli addebiti all'incolpato, entro 90 giorni dalla data in cui l'amministrazione ha avuto conoscenza integrale della sentenza o del decreto penale irrevocabili, che lo concludono, ovvero […]"},
    "cp_120": {"norma": "art. 120 c.p.", "titolo": "Diritto di querela", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1930-10-19;1398~art120", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Ogni persona offesa da un reato per cui non debba procedersi d'ufficio o dietro richiesta o istanza ha diritto di querela. Per i minori degli anni quattordici e per gli interdetti a cagione d'infermita' di mente, il diritto di querela e' esercitato dal genitore o dal tutore."},
    "cp_124": {"norma": "art. 124 c.p.", "titolo": "Termine per proporre la querela. Rinuncia", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1930-10-19;1398~art124", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Salvo che la legge disponga altrimenti, il diritto di querela non puo' essere esercitato, decorsi tre mesi dal giorno della notizia del fatto che costituisce il reato. Il diritto di querela non puo' essere esercitato se vi e' stata rinuncia espressa o tacita da parte di colui al quale ne spetta l'esercizio."},
    "cp_168bis": {"norma": "art. 168-bis c.p.", "titolo": "Sospensione del procedimento con messa alla prova dell'imputato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1930-10-19;1398~art168bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Nei procedimenti per reati puniti con la sola pena edittale pecuniaria o con la pena edittale detentiva non superiore nel massimo a quattro anni, sola, congiunta o alternativa alla pena pecuniaria, nonche' per i delitti indicati dal comma 2 dell'articolo 550 del codice di procedura penale , l'imputato, anche su proposta del pubblico ministero, puo' chiedere la sospensione del processo con messa alla prova."},
    "cpa_113": {"norma": "art. 113 c.p.a.", "titolo": "Giudice dell'ottemperanza", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-07-02;104~art113", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorso si propone, nel caso di cui all'articolo 112, comma 2, lettere a) e b), al giudice che ha emesso il provvedimento della cui ottemperanza si tratta; la competenza è del tribunale amministrativo regionale anche per i suoi provvedimenti confermati in appello con motivazione che abbia lo stesso contenuto dispositivo e conformativo dei provvedimenti di primo grado. 2."},
    "cpa_114": {"norma": "art. 114 c.p.a.", "titolo": "Procedimento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-07-02;104~art114", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. L'azione si propone, anche senza previa diffida, con ricorso notificato alla pubblica amministrazione e a tutte le altre parti del giudizio definito dalla sentenza o dal lodo della cui ottemperanza si tratta; l'azione si prescrive con il decorso di dieci anni dal passaggio in giudicato della sentenza. 2."},
    "cpa_117": {"norma": "art. 117 c.p.a.", "titolo": "Ricorsi avverso il silenzio", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-07-02;104~art117", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorso avverso il silenzio è proposto, anche senza previa diffida, con atto notificato all'amministrazione e ad almeno un controinteressato nel termine di cui all'articolo 31, comma 2. 2. Il ricorso è deciso con sentenza in forma semplificata e in caso di totale o parziale accoglimento il giudice ordina all'amministrazione di provvedere entro un termine non superiore, di norma, a trenta giorni. 3."},
    "cpa_136": {"norma": "art. 136 c.p.a.", "titolo": "Disposizioni sulle comunicazioni e sui depositi informatici", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-07-02;104~art136", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. I difensori indicano nel ricorso o nel primo atto difensivo un recapito di fax, che può essere anche diverso da quello del domiciliatario. La comunicazione a mezzo fax è eseguita esclusivamente qualora sia impossibile effettuare la comunicazione all'indirizzo di posta elettronica certificata risultante da pubblici elenchi, per mancato funzionamento del sistema informatico della giustizia amministrativa."},
    "cpa_31": {"norma": "art. 31 c.p.a.", "titolo": "Azione avverso il silenzio e declaratoria di nullità", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-07-02;104~art31", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Decorsi i termini per la conclusione del procedimento amministrativo e negli altri casi previsti dalla legge , chi vi ha interesse può chiedere l'accertamento dell'obbligo dell'amministrazione di provvedere. 2. L'azione può essere proposta fintanto che perdura l'inadempimento e, comunque, non oltre un anno dalla scadenza del termine di conclusione del procedimento."},
    "cpa_40": {"norma": "art. 40 c.p.a.", "titolo": "Contenuto del ricorso", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-07-02;104~art40", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorso deve contenere distintamente: a) gli elementi identificativi del ricorrente, del suo difensore e delle parti nei cui confronti il ricorso è proposto; b) l'indicazione dell'oggetto della domanda, ivi compreso l'atto o il provvedimento eventualmente impugnato, e la data della sua notificazione, comunicazione o comunque della sua conoscenza; c) l'esposizione sommaria dei fatti; d) i motivi specifici su […]"},
    "cpa_55": {"norma": "art. 55 c.p.a.", "titolo": "Misure cautelari collegiali", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-07-02;104~art55", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Se il ricorrente, allegando di subire un pregiudizio grave e irreparabile durante il tempo necessario a giungere alla decisione sul ricorso, chiede l'emanazione di misure cautelari, compresa l'ingiunzione a pagare una somma in via provvisoria, che appaiono, secondo le circostanze, più idonee ad assicurare interinalmente gli effetti della decisione sul ricorso, il collegio si pronuncia con ordinanza emessa in […]"},
    "cpa_56": {"norma": "art. 56 c.p.a.", "titolo": "Misure cautelari monocratiche", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-07-02;104~art56", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Prima della trattazione della domanda cautelare da parte del collegio, in caso di estrema gravità ed urgenza, tale da non consentire neppure la dilazione fino alla data della camera di consiglio, il ricorrente può, con la domanda cautelare o con distinto ricorso notificato alle controparti, chiedere al presidente del tribunale amministrativo regionale, o della sezione cui il ricorso è assegnato, di disporre […]"},
    "cpa_62": {"norma": "art. 62 c.p.a.", "titolo": "Appello cautelare", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-07-02;104~art62", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Contro le ordinanze cautelari è ammesso appello al Consiglio di Stato, da proporre nel termine di trenta giorni dalla notificazione dell'ordinanza, ovvero di sessanta giorni dalla sua pubblicazione. 2. L'appello, depositato nel termine di cui all'articolo 45, è deciso in camera di consiglio con ordinanza. Al giudizio si applicano gli articoli 55, comma 2 e commi da 5 a 10, 56 e 57. 3."},
    "cpa_93": {"norma": "art. 93 c.p.a.", "titolo": "Luogo di notificazione dell'impugnazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-07-02;104~art93", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. L'impugnazione deve essere notificata nella residenza dichiarata o nel domicilio eletto dalla parte nell'atto di notificazione della sentenza o, in difetto, presso il difensore o nella residenza dichiarata o nel domicilio eletto per il giudizio e risultante dalla sentenza. 2."},
    "cpc_360": {"norma": "art. 360 c.p.c.", "titolo": "Sentenze impugnabili e motivi di ricorso", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art360", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Le sentenze pronunciate in grado d'appello o in unico grado possono essere impugnate con ricorso per cassazione: 1) per motivi attinenti alla giurisdizione; 2) per violazione delle norme sulla competenza, quando non e' prescritto il regolamento di competenza; 3) per violazione o falsa applicazione di norme di diritto e dei contratti e accordi collettivi nazionali di lavoro; 4) per nullita' della sentenza o del […]"},
    "cpc_395": {"norma": "art. 395 c.p.c.", "titolo": "Casi di revocazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art395", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Le sentenze pronunciate in grado d'appello o in unico grado possono essere impugnate per revocazione: 1) se sono l'effetto del dolo di una delle parti in danno dell'altra; 2) se si e' giudicato in base a prove riconosciute o comunque dichiarate false dopo la sentenza oppure che la parte soccombente ignorava essere state riconosciute o dichiarate tali prima della sentenza; 3) se dopo la sentenza sono stati trovati […]"},
    "cpc_398": {"norma": "art. 398 c.p.c.", "titolo": "Proposizione della domanda", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art398", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "La revocazione si propone con citazione davanti allo stesso giudice che ha pronunciato la sentenza impugnata. La citazione deve indicare, a pena d'inammissibilita', il motivo della revocazione e le prove relative alla dimostrazione dei fatti di cui ai numeri 1, 2, 3 e 6 dell'articolo 395, del giorno della scoperta o dell'accertamento del dolo o della falsita', o del recupero dei documenti."},
    "cpc_409": {"norma": "art. 409 c.p.c.", "titolo": "Controversie individuali di lavoro", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art409", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Si osservano le disposizioni del presente capo nelle controversie relative a: 1) rapporti di lavoro subordinato privato, anche se non inerenti all'esercizio di una impresa; 2) rapporti di mezzadria, di colonia parziaria, di compartecipazione agraria, di affitto a coltivatore diretto, nonche' rapporti derivanti da altri contratti agrari, salva la competenza delle sezioni specializzate agrarie; 3) rapporti di agenzia, […]"},
    "cpc_410": {"norma": "art. 410 c.p.c.", "titolo": "Tentativo di conciliazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art410", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Chi intende propone in giudizio una domanda relativa ai rapporti previsti dall'articolo 409 puo' promuovere, anche tramite l'associazione sindacale alla quale aderisce o conferisce mandato, un previo tentativo di conciliazione presso la commissione di conciliazione individuata secondo i criteri di cui all'articolo 413."},
    "cpc_413": {"norma": "art. 413 c.p.c.", "titolo": "Giudice competente", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art413", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Le controversie previste dall'articolo 409 sono in primo grado di competenza del tribunale in funzione di giudice del lavoro. Competente per territorio e' il giudice nella cui circoscrizione e' sorto il rapporto ovvero si trova l'azienda o una sua dipendenza alla quale e' addetto il lavoratore o presso la quale egli prestava la sua opera al momento della fine del rapporto."},
    "cpc_441bis": {"norma": "art. 441-bis c.p.c.", "titolo": "Controversie in materia di licenziamento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art441bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "La trattazione e la decisione delle controversie aventi ad oggetto l'impugnazione dei licenziamenti nelle quali e' proposta domanda di reintegrazione nel posto di lavoro hanno carattere prioritario rispetto alle altre pendenti sul ruolo del giudice, anche quando devono essere risolte questioni relative alla qualificazione del rapporto."},
    "cpc_442": {"norma": "art. 442 c.p.c.", "titolo": "Controversie in materia di previdenza e di assistenza obbligatorie", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art442", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Nei procedimenti relativi a controversie derivanti dall'applicazione delle norme riguardanti le assicurazioni sociali, gli infortuni sul lavoro, le malattie professionali, gli assegni familiari nonche' ogni altra forma di previdenza e di assistenza obbligatorie, si osservano le disposizioni di cui al capo primo di questo titolo."},
    "cpc_444": {"norma": "art. 444 c.p.c.", "titolo": "Giudice competente", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art444", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Le controversie in materia di previdenza e di assistenza obbligatorie indicate nell'articolo 442 sono di competenza del tribunale, in funzione di giudice del lavoro, nella cui circoscrizione ha la residenza l'attore."},
    "cpc_445bis": {"norma": "art. 445-bis c.p.c.", "titolo": "Accertamento tecnico preventivo obbligatorio", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art445bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Nelle controversie in materia di invalidita' civile, cecita' civile, sordita' civile, handicap e disabilita', nonche' di pensione di inabilita' e di assegno di invalidita', disciplinati dalla legge 12 giugno 1984, n."},
    "cpc_447bis": {"norma": "art. 447-bis c.p.c.", "titolo": "Norme applicabili alle controversie in materia di locazione, di comodato e di affitto", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art447bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Le controversie in materia di locazione e di comodato di immobili urbani e quelle di affitto di aziende sono disciplinate dagli articoli 414, 415, 416, 417, 418, 419, 420, 421, primo comma, 422, 423, primo e terzo comma, 424, 425, 426, 427, 428, 429, primo e secondo comma, 430, 433, 434, 435, 436, 436-bis, 437, 438, 439, 440, 441, in quanto applicabili. PERIODO SOPPRESSO DAL D.LGS. 19 FEBBRAIO 1998, N. 51 ."},
    "cpc_473bis_10": {"norma": "art. 473-bis.10 c.p.c.", "titolo": "Mediazione familiare", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis10", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il giudice puo', in ogni momento, informare le parti della possibilita' di avvalersi della mediazione familiare e invitarle a rivolgersi a un mediatore, da loro scelto tra le persone iscritte nell'elenco formato a norma delle disposizioni di attuazione del presente codice, per ricevere informazioni circa le finalita', i contenuti e le modalita' del percorso e per valutare se intraprenderlo."},
    "cpc_473bis_12": {"norma": "art. 473-bis.12 c.p.c.", "titolo": "Forma della domanda", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis12", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "La domanda si propone con ricorso che contiene: a) l'indicazione dell'ufficio giudiziario davanti al quale la domanda e' proposta; b) il nome, il cognome, il luogo e la data di nascita, la cittadinanza, la residenza o il domicilio o la dimora e il codice fiscale dell'attore e del convenuto, nonche' dei figli comuni delle parti se minorenni, maggiorenni economicamente non autosufficienti o portatori di handicap […]"},
    "cpc_473bis_29": {"norma": "art. 473-bis.29 c.p.c.", "titolo": "Modificabilita' dei provvedimenti", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis29", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Qualora sopravvengano giustificati motivi, le parti possono in ogni tempo chiedere, con le forme previste nella presente sezione, la revisione dei provvedimenti a tutela dei minori e in materia di contributi economici."},
    "cpc_473bis_4": {"norma": "art. 473-bis.4 c.p.c.", "titolo": "Ascolto del minore", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis4", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il minore che ha compiuto gli anni dodici e anche di eta' inferiore ove capace di discernimento e' ascoltato dal giudice nei procedimenti nei quali devono essere adottati provvedimenti che lo riguardano. Le opinioni del minore devono essere tenute in considerazione avuto riguardo alla sua eta' e al suo grado di maturita'."},
    "cpc_473bis_47": {"norma": "art. 473-bis.47 c.p.c.", "titolo": "Competenza per territorio", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis47", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Poteri del pubblico ministero . Per le domande di separazione personale dei coniugi, scioglimento o cessazione degli effetti civili del matrimonio, scioglimento dell'unione civile e regolamentazione dell'esercizio della responsabilita' genitoriale nei confronti dei figli nati fuori dal matrimonio, nonche' per quelle di modifica delle relative condizioni, e' competente il tribunale individuato ai sensi dell'articolo […]"},
    "cpc_473bis_49": {"norma": "art. 473-bis.49 c.p.c.", "titolo": "Cumulo di domande di separazione e scioglimento o cessazione degli effetti civili del matrimonio", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis49", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Negli atti introduttivi del procedimento di separazione personale le parti possono proporre anche domanda di scioglimento o cessazione degli effetti civili del matrimonio e le domande a questa connesse. Le domande cosi' proposte sono procedibili decorso il termine a tal fine previsto dalla legge, e previo passaggio in giudicato della sentenza che pronuncia la separazione personale."},
    "cpc_473bis_51": {"norma": "art. 473-bis.51 c.p.c.", "titolo": "Procedimento su domanda congiunta", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis51", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "La domanda congiunta relativa ai procedimenti di cui all'articolo 473-bis.47 si propone con ricorso al tribunale del luogo di residenza o di domicilio dell'una o dell'altra parte."},
    "cpc_473bis_52": {"norma": "art. 473-bis.52 c.p.c.", "titolo": "Forma della domanda", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis52", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "La domanda per interdizione o inabilitazione si propone con ricorso diretto al tribunale del luogo in cui la persona nei confronti della quale e' proposta ha residenza o domicilio."},
    "cpc_473bis_56": {"norma": "art. 473-bis.56 c.p.c.", "titolo": "Impugnazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis56", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "La sentenza che provvede sulla domanda d'interdizione o d'inabilitazione puo' essere impugnata da tutti coloro che avrebbero avuto diritto di proporre la domanda, anche se non hanno partecipato al giudizio, e dal tutore o curatore nominato con la stessa sentenza."},
    "cpc_473bis_58": {"norma": "art. 473-bis.58 c.p.c.", "titolo": "Procedimenti in materia di amministrazione di sostegno", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis58", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Ai procedimenti in materia di amministrazione di sostegno si applicano, in quanto compatibili, le disposizioni della presente sezione. Contro i decreti del giudice tutelare e' ammesso reclamo al tribunale ai sensi dell'articolo 739. Contro il decreto del tribunale in composizione collegiale e' ammesso ricorso per cassazione."},
    "cpc_473bis_69": {"norma": "art. 473-bis.69 c.p.c.", "titolo": "Ordini di protezione contro gli abusi familiari", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis69", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Quando la condotta del coniuge o di altro convivente e' causa di grave pregiudizio all'integrita' fisica o morale ovvero alla liberta' dell'altro coniuge o convivente, il giudice, su istanza di parte, puo' adottare con decreto uno o piu' dei provvedimenti di cui all'articolo 473-bis.70. I medesimi provvedimenti possono essere adottati, ricorrendone i presupposti, anche quando la convivenza e' cessata."},
    "cpc_473bis_70": {"norma": "art. 473-bis.70 c.p.c.", "titolo": "Contenuto degli ordini di protezione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis70", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Con il decreto di cui all'articolo 473-bis.69 il giudice ordina al coniuge o convivente, che ha tenuto la condotta pregiudizievole, la cessazione della stessa condotta e dispone l'allontanamento dalla casa familiare del coniuge o del convivente che ha tenuto la condotta pregiudizievole prescrivendogli altresi', ove occorra, di non avvicinarsi ai luoghi abitualmente frequentati dal beneficiario dell'ordine di […]"},
    "cpc_473bis_71": {"norma": "art. 473-bis.71 c.p.c.", "titolo": "Provvedimenti di adozione degli ordini di protezione contro gli abusi familiari", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art473bis71", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "L'istanza si propone, anche dalla parte personalmente, con ricorso al tribunale del luogo di residenza o di domicilio dell'istante, che provvede in camera di consiglio in composizione monocratica. Il presidente del tribunale designa il giudice a cui e' affidata la trattazione del ricorso."},
    "cpc_513": {"norma": "art. 513 c.p.c.", "titolo": "Ricerca delle cose da pignorare", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art513", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "L'ufficiale giudiziario, munito del titolo esecutivo e del precetto, puo' ricercare le cose da pignorare nella casa del debitore e negli altri luoghi a lui appartenenti. Puo' anche ricercarle sulla persona del debitore, osservando le opportune cautele per rispettarne il decoro."},
    "cpc_555": {"norma": "art. 555 c.p.c.", "titolo": "Forma del pignoramento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art555", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il pignoramento immobiliare si esegue mediante notificazione al debitore e successiva trascrizione di un atto nel quale gli si indicano esattamente, con gli estremi richiesti dal codice civile per l'individuazione dell'immobile ipotecato, i beni e i diritti immobiliari che si intendono sottoporre a esecuzione, e gli si fa l'ingiunzione prevista nell'articolo 492."},
    "cpc_567": {"norma": "art. 567 c.p.c.", "titolo": "Istanza di vendita", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art567", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Decorso il termine di cui all'articolo 501, il creditore pignorante e ognuno dei creditori intervenuti muniti di titolo esecutivo possono chiedere la vendita dell'immobile pignorato."},
    "cpc_624": {"norma": "art. 624 c.p.c.", "titolo": "Sospensione per opposizione all'esecuzione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art624", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Se e' proposta opposizione all'esecuzione a norma degli articoli 615 e 619, il giudice dell'esecuzione, concorrendo gravi motivi, sospende, su istanza di parte, il processo con cauzione o senza. Contro l'ordinanza che provvede sull'istanza di sospensione e' ammesso reclamo ai sensi dell'articolo 669-terdecies."},
    "cpc_634": {"norma": "art. 634 c.p.c.", "titolo": "Prova scritta", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art634", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Sono prove scritte idonee a norma del numero 1 dell'articolo precedente le polizze e promesse unilaterali per scrittura privata e i telegrammi, anche se mancanti dei requisiti prescritti dal codice civile ."},
    "cpc_636": {"norma": "art. 636 c.p.c.", "titolo": "Parcella delle spese e prestazioni", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art636", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Nei casi previsti nei numeri 2 e 3 dell'articolo 633, la domanda deve essere accompagnata dalla parcella delle spese e prestazioni, munita della sottoscrizione del ricorrente e corredata dal parere della competente associazione professionale. Il parere non occorre se l'ammontare delle spese e delle prestazioni e' determinato in base a tariffe obbligatorie."},
    "cpc_642": {"norma": "art. 642 c.p.c.", "titolo": "Esecuzione provvisoria", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art642", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Se il credito e' fondato su cambiale, assegno bancario, assegno circolare, certificato di liquidazione di borsa, o su atto ricevuto da notaio o da altro pubblico ufficiale autorizzato, il giudice, su istanza del ricorrente, ingiunge al debitore di pagare o consegnare senza dilazione, autorizzando in mancanza l'esecuzione provvisoria del decreto e fissando il termine ai soli effetti dell'opposizione."},
    "cpc_657": {"norma": "art. 657 c.p.c.", "titolo": "Intimazione di licenza e di sfratto per finita locazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art657", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il locatore o il concedente puo' intimare al conduttore, al comodatario di beni immobili, all'affittuario di azienda, all'affittuario coltivatore diretto, al mezzadro o al colono licenza per finita locazione, prima della scadenza del contratto, con la contestuale citazione per la convalida, rispettando i termini prescritti dal contratto, dalla legge o dagli usi locali."},
    "cpc_658": {"norma": "art. 658 c.p.c.", "titolo": "Intimazione di sfratto per morosita'", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art658", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il locatore puo' intimare al conduttore , all'affittuario di azienda, all'affittuario coltivatore diretto, al mezzadro o al colono lo sfratto con le modalita' stabilite nell'articolo precedente anche in caso di mancato pagamento del canone di affitto alle scadenze, e chiedere nello stesso atto l'ingiunzione di pagamento per i canoni scaduti."},
    "cpc_663": {"norma": "art. 663 c.p.c.", "titolo": "Mancata comparizione o mancata opposizione dell'intimato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art663", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Se l'intimato non compare o comparendo non si oppone, il giudice convalida con ordinanza esecutiva la licenza o lo sfratto. Il giudice ordina che sia rinnovata la citazione, se risulta o appare probabile che l'intimato non abbia avuto conoscenza della citazione stessa o non sia potuto comparire per caso fortuito o forza maggiore."},
    "cpc_665": {"norma": "art. 665 c.p.c.", "titolo": "Opposizione, provvedimenti del giudice", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art665", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Se l'intimato comparisce e oppone eccezioni non fondate su prova scritta, il giudice, su istanza del locatore, se non sussistono gravi motivi in contrario, pronuncia ordinanza non impugnabile di rilascio, con riserva delle eccezioni del convenuto. L'ordinanza e' immediatamente esecutiva, ma puo' essere subordinata alla prestazione di una cauzione per i danni e le spese."},
    "cpc_667": {"norma": "art. 667 c.p.c.", "titolo": "Mutamento del rito", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art667", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Pronunciati i provvedimenti previsti dagli articoli 665 e 666, il giudizio prosegue nelle forme del rito speciale, previa ordinanza di mutamento di rito ai sensi dell'articolo 426."},
    "cpc_668": {"norma": "art. 668 c.p.c.", "titolo": "Opposizione dopo la convalida", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art668", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Se l'intimazione di licenza o di sfratto e' stata convalidata in assenza dell'intimato, questi puo' farvi opposizione provando di non averne avuto tempestiva conoscenza per irregolarita' della notificazione o per caso fortuito o forza maggiore. Se sono decorsi dieci giorni dall'esecuzione, l'opposizione non e' piu' ammessa, e la cauzione, prestata a norma dell'articolo 663 secondo comma, e' liberata."},
    "cpc_669bis": {"norma": "art. 669-bis c.p.c.", "titolo": "Forma della domanda", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art669bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Art. 669-bis c.p.c. (Forma della domanda), testo integrale: La domanda si propone con ricorso al giudice competente."},
    "cpc_669novies": {"norma": "art. 669-novies c.p.c.", "titolo": "Inefficacia del provvedimento cautelare", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art669novies", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Se il procedimento di merito non e' iniziato nel termine perentorio di cui all'articolo 669 octies, ovvero se successivamente al suo inizio si estingue, il provvedimento cautelare perde la sua efficacia."},
    "cpc_670": {"norma": "art. 670 c.p.c.", "titolo": "Sequestro giudiziario", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art670", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il giudice puo' autorizzare il sequestro giudiziario: 1) di beni mobili o immobili, aziende o altre universalita' di beni, quando ne e' controversa la proprieta' o il possesso, ed e' opportuno provvedere alla loro custodia o alla loro gestione temporanea; 2) di libri, registri, documenti, modelli, campioni e di ogni altra cosa da cui si pretende desumere elementi di prova, quando e' controverso il diritto alla […]"},
    "cpc_671": {"norma": "art. 671 c.p.c.", "titolo": "Sequestro conservativo", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art671", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il giudice, su istanza del creditore che ha fondato timore di perdere la garanzia del proprio credito, puo' autorizzare il sequestro conservativo di beni mobili o immobili del debitore o delle somme e cose a lui dovute, nei limiti in cui la legge ne permette il pignoramento."},
    "cpc_686": {"norma": "art. 686 c.p.c.", "titolo": "Conversione del sequestro conservativo in pignoramento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art686", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il sequestro conservativo si converte in pignoramento al momento in cui il creditore sequestrante ottiene sentenza di condanna esecutiva. Se i beni sequestrati sono stati oggetto di esecuzione da parte di altri creditori, il sequestrante partecipa con essi alla distribuzione della somma ricavata."},
    "cpc_687": {"norma": "art. 687 c.p.c.", "titolo": "Casi speciali di sequestro", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art687", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il giudice puo' ordinare il sequestro delle somme o delle cose che il debitore ha offerto o messo comunque a disposizione del creditore per la sua liberazione, quando e' controverso l'obbligo o il modo del pagamento o della consegna, o l'idoneita' della cosa offerta."},
    "cpc_692": {"norma": "art. 692 c.p.c.", "titolo": "Assunzione di testimoni", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art692", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Chi ha fondato motivo di temere che siano per mancare uno o piu' testimoni, le cui deposizioni possono essere necessarie in una causa da proporre, puo' chiedere che ne sia ordinata l'audizione a futura memoria."},
    "cpc_693": {"norma": "art. 693 c.p.c.", "titolo": "Istanza", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art693", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "L'istanza si propone con ricorso al giudice che sarebbe competente per la causa di merito. In caso d'eccezionale urgenza, l'istanza puo' anche proporsi al tribunale del luogo in cui la prova deve essere assunta."},
    "cpc_694": {"norma": "art. 694 c.p.c.", "titolo": "Ordine di comparizione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art694", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il presidente del tribunale o il conciliatore fissa, con decreto, l'udienza di comparizione e stabilisce il termine perentorio per la notificazione del decreto."},
    "cpc_696": {"norma": "art. 696 c.p.c.", "titolo": "Accertamento tecnico e ispezione giudiziale", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art696", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Chi ha urgenza di far verificare, prima del giudizio, lo stato di luoghi o la qualita' o la condizione di cose, puo' chiedere, a norma degli articoli 692 e seguenti, che sia disposto un accertamento tecnico o un'ispezione giudiziale."},
    "cpc_696bis": {"norma": "art. 696-bis c.p.c.", "titolo": "Consulenza tecnica preventiva ai fini della composizione della lite", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art696bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "L'espletamento di una consulenza tecnica, in via preventiva, puo' essere richiesto anche al di fuori delle condizioni di cui al primo comma dell'articolo 696, ai fini dell'accertamento e della relativa determinazione dei crediti derivanti dalla mancata o inesatta esecuzione di obbligazioni contrattuali o da fatto illecito. Il giudice procede a norma del terzo comma del medesimo articolo 696."},
    "cpc_700": {"norma": "art. 700 c.p.c.", "titolo": "Condizioni per la concessione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art700", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Fuori dei casi regolati nelle precedenti sezioni di questo capo, chi ha fondato motivo di temere che durante il tempo occorrente per far valere il suo diritto in via ordinaria, questo sia minacciato da un pregiudizio imminente e irreparabile, puo' chiedere con ricorso al giudice i provvedimenti d'urgenza, che appaiono, secondo le circostanze, piu' idonei ad assicurare provvisoriamente gli effetti della decisione sul […]"},
    "cpc_703": {"norma": "art. 703 c.p.c.", "titolo": "Domande di reintegrazione e di manutenzione nel possesso", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art703", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Le domande di reintegrazione e di manutenzione nel possesso si propongono con ricorso al giudice competente a norma dell'articolo 21. Il giudice provvede ai sensi degli articoli 669-bis e seguenti, in quanto compatibili . L'ordinanza che accoglie o respinge la domanda e' reclamabile ai sensi dell'articolo 669-terdecies."},
    "cpc_840bis": {"norma": "art. 840-bis c.p.c.", "titolo": "Ambito di applicazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art840bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "I diritti individuali omogenei sono tutelabili anche attraverso l'azione di classe, secondo le disposizioni del presente titolo. A tale fine, un'organizzazione o un'associazione senza scopo di lucro i cui obiettivi statutari comprendano la tutela dei predetti diritti o ciascun componente della classe puo' agire nei confronti dell'autore della condotta lesiva per l'accertamento della responsabilita' e per la condanna […]"},
    "cpc_840undecies": {"norma": "art. 840-undecies c.p.c.", "titolo": "Impugnazione del decreto", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1940-10-28;1443~art840undecies", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Contro il decreto di cui all'articolo 840-octies, quinto comma, puo' essere proposta opposizione con ricorso depositato presso il tribunale . Il ricorso puo' essere proposto dal resistente, dal rappresentante comune degli aderenti e dagli avvocati di cui all'articolo 840-novies, sesto e settimo comma, nel termine perentorio di trenta giorni dalla comunicazione del provvedimento."},
    "cpi_120": {"norma": "art. 120 c.p.i.", "titolo": "Giurisdizione e competenza", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2005-02-10;30~art120", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le azioni in materia di proprieta' industriale i cui titoli sono concessi o in corso di concessione si propongono avanti l'autorita' giudiziaria dello Stato, qualunque sia la cittadinanza, il domicilio o la residenza delle parti."},
    "cpi_131": {"norma": "art. 131 c.p.i.", "titolo": "Inibitoria", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2005-02-10;30~art131", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il titolare di un diritto di proprieta' industriale puo' chiedere che sia disposta l'inibitoria di qualsiasi violazione imminente del suo diritto e del proseguimento o della ripetizione delle violazioni in atto, ed in particolare puo' chiedere che siano disposti l'inibitoria della fabbricazione, del commercio e dell'uso delle cose costituenti violazione del diritto, e l'ordine di ritiro dal commercio delle […]"},
    "cpi_82": {"norma": "art. 82 c.p.i.", "titolo": "Oggetto del brevetto", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2005-02-10;30~art82", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Possono costituire oggetto di brevetto per modello di utilita' i nuovi modelli atti a conferire particolare efficacia o comodita' di applicazione o di impiego a macchine, o parti di esse, strumenti, utensili od oggetti di uso in genere, quali i nuovi modelli consistenti in particolari conformazioni, disposizioni, configurazioni o combinazioni di parti. 2."},
    "cpi_86": {"norma": "art. 86 c.p.i.", "titolo": "Rinvio", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2005-02-10;30~art86", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le disposizioni della sezione IV, sulle invenzioni industriali, oltre che a tali invenzioni, spiegano effetto anche nella materia dei modelli di utilita', in quanto applicabili. 2. In particolare sono estese ai brevetti per modello di utilita' le disposizioni in materia di invenzioni dei dipendenti e licenze obbligatorie."},
    "cpmp_1": {"norma": "art. 1 c.p.m.p.", "titolo": "CODICE PENALE MILITARE DI PACE Art", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1941-02-20;303~art1", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. (Persone soggette alla legge penale militare). La legge penale militare si applica ai militari in servizio alle armi e a quelli considerati tali. La legge determina i casi, nei quali la legge penale militare si applica ai militari in congedo, ai militari in congedo assoluto, agli assimilati ai militari, agli iscritti ai corpi civili militarmente ordinati e a ogni altra persona estranea alle forze armate dello […]"},
    "cpmp_263": {"norma": "art. 263 c.p.m.p.", "titolo": "Giurisdizione militare in relazione alle persone e ai reati militari", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1941-02-20;303~art263", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Appartiene ai tribunali militari la cognizione dei reati militari commessi dalle persone alle quali è applicabile la legge penale militare."},
    "cpmp_264": {"norma": "art. 264 c.p.m.p.", "titolo": "Connessione di procedimenti", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1941-02-20;303~art264", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Tra i procedimenti di competenza della autorità giudiziaria ordinaria e i procedimenti di competenza dell'autorità giudiziaria militare si ha connessione solamente quando essi riguardano delitti commessi nello stesso tempo da più persone riunite o da più persone anche in tempi e luoghi diversi, ma in concorso tra loro, o da più persone in danno reciprocamente le une delle altre, Ovvero delitti commessi gli uni per […]"},
    "cpmp_37": {"norma": "art. 37 c.p.m.p.", "titolo": "Reato militare", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1941-02-20;303~art37", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Qualunque violazione della legge penale militare è reato militare. È reato esclusivamente militare quello costituito da un fatto che, nei suoi elementi materiali costitutivi, non è, in tutto o in parte, preveduto come reato dalla legge penale comune. I reati preveduti da questo codice, e quelli per i quali qualsiasi altra legge penale militare commina una delle pene indicate nell'articolo 22, sono delitti."},
    "cpp_129bis": {"norma": "art. 129-bis c.p.p.", "titolo": "Accesso ai programmi di giustizia riparativa", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art129bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. In ogni stato e grado del procedimento l'autorita' giudiziaria puo' disporre, anche d'ufficio, l'invio dell'imputato e della vittima del reato di cui all'articolo 42, comma 1, lettera b), del decreto legislativo 10 ottobre 2022, n. 150 , al Centro per la giustizia riparativa di riferimento, per l'avvio di un programma di giustizia riparativa. 2."},
    "cpp_175": {"norma": "art. 175 c.p.p.", "titolo": "Restituzione nel termine", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art175", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il pubblico ministero, le parti private e i difensori sono restituiti nel termine stabilito a pena di decadenza, se provano di non averlo potuto osservare per caso fortuito o per forza maggiore. La richiesta per la restituzione nel termine e' presentata, a pena di decadenza, entro dieci giorni da quello nel quale e' cessato il fatto costituente caso fortuito o forza maggiore. 2."},
    "cpp_299": {"norma": "art. 299 c.p.p.", "titolo": "Revoca e sostituzione delle misure", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art299", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le misure coercitive e interdittive sono immediatamente revocate quando risultano mancanti, anche per fatti sopravvenuti, le condizioni di applicabilita' previste dall'articolo 273 o dalle disposizioni relative alle singole misure ovvero le esigenze cautelari previste dall'articolo 274. 2. Salvo quanto previsto dall' art."},
    "cpp_309": {"norma": "art. 309 c.p.p.", "titolo": "Riesame delle ordinanze che dispongono una misura coercitiva", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art309", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Entro dieci giorni dalla esecuzione o notificazione del provvedimento, l'imputato puo' proporre richiesta di riesame, anche nel merito, della ordinanza che dispone una misura coercitiva, salvo che si tratti di ordinanza emessa a seguito di appello del pubblico ministero. 2. Per l'imputato latitante il termine decorre dalla data di notificazione eseguita a norma dell'articolo 165."},
    "cpp_310": {"norma": "art. 310 c.p.p.", "titolo": "A p p e l l o", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art310", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Fuori dei casi previsti dall'articolo 309 comma 1, il pubblico ministero, l'imputato e il suo difensore possono proporre appello contro le ordinanze in materia di misure cautelari personali, enunciandone contestualmente i motivi. 2. Si osservano le disposizioni dell'articolo 309 commi 1, 2, 3, 4 e 7."},
    "cpp_311": {"norma": "art. 311 c.p.p.", "titolo": "Ricorso per cassazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art311", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Contro le decisioni emesse a norma degli articoli 309 e 310, il pubblico ministero che ha richiesto l'applicazione della misura, l'imputato e il suo difensore possono proporre ricorso per cassazione entro dieci giorni dalla comunicazione o dalla notificazione dell'avviso di deposito del provvedimento."},
    "cpp_314": {"norma": "art. 314 c.p.p.", "titolo": "Presupposti e modalita' della decisione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art314", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Chi e' stato prosciolto con sentenza irrevocabile perche' il fatto non sussiste, per non aver commesso il fatto, perche' il fatto non costituisce reato o non e' previsto dalla legge come reato, ha diritto a un'equa riparazione per la custodia cautelare subita, qualora non vi abbia dato o concorso a darvi causa per dolo o colpa grave."},
    "cpp_315": {"norma": "art. 315 c.p.p.", "titolo": "Procedimento per la riparazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art315", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La domanda di riparazione deve essere proposta, a pena di inammissibilita', entro due anni dal giorno in cui la sentenza di proscioglimento o di condanna e' divenuta irrevocabile, la sentenza di non luogo a procedere e' divenuta inoppugnabile o e' stata effettuata la notificazione del provvedimento di archiviazione alla persona nei cui confronti e' stato pronunciato a norma del comma 3 dell'articolo 314; 2."},
    "cpp_322": {"norma": "art. 322 c.p.p.", "titolo": "Riesame del decreto di sequestro preventivo", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art322", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Contro il decreto di sequestro emesso dal giudice l'imputato e il suo difensore, la persona alla quale le cose sono state sequestrate e quella che avrebbe diritto alla loro restituzione nonche' le associazioni e gli enti di cui all'articolo 19-quater delle disposizioni di coordinamento e transitorie per il codice penale possono proporre richiesta di riesame, anche nel merito, a norma dell'articolo 324. 2."},
    "cpp_324": {"norma": "art. 324 c.p.p.", "titolo": "Procedimento di riesame", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art324", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La richiesta di riesame e' presentata, nella cancelleria del tribunale indicato nel comma 5, entro dieci giorni dalla data di esecuzione del provvedimento che ha disposto il sequestro o dalla diversa data in cui l'interessato ha avuto conoscenza dell'avvenuto sequestro. 2. La richiesta e' presentata con le forme previste dall'articolo 582."},
    "cpp_325": {"norma": "art. 325 c.p.p.", "titolo": "Ricorso per cassazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art325", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Contro le ordinanze emesse a norma degli articoli 322-bis e 324, il pubblico ministero, l'imputato e il suo difensore, la persona alla quale le cose sono state sequestrate e quella che avrebbe diritto alla loro restituzione nonche' le associazioni e gli enti di cui all'articolo 19-quater delle disposizioni di coordinamento e transitorie per il codice penale possono proporre ricorso per cassazione per violazione […]"},
    "cpp_336": {"norma": "art. 336 c.p.p.", "titolo": "Querela", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art336", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La querela e' proposta mediante dichiarazione nella quale, personalmente o a mezzo di procuratore speciale, si manifesta la volonta' che si proceda in ordine a un fatto previsto dalla legge come reato."},
    "cpp_337": {"norma": "art. 337 c.p.p.", "titolo": "Formalita' della querela", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art337", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La dichiarazione di querela e' proposta, con le forme previste dall'articolo 333 comma 2, alle autorita' alle quali puo' essere presentata denuncia ovvero a un agente consolare all'estero. Essa, con sottoscrizione autentica, puo' essere anche recapitata da un incaricato o spedita per posta in piego raccomandato. 2."},
    "cpp_408": {"norma": "art. 408 c.p.p.", "titolo": "Richiesta di archiviazione per infondatezza della notizia di reato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art408", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Quando gli elementi acquisiti nel corso delle indagini preliminari non consentono di formulare una ragionevole previsione di condanna o di applicazione di una misura di sicurezza diversa dalla confisca, il pubblico ministero, presenta al giudice richiesta di archiviazione."},
    "cpp_409": {"norma": "art. 409 c.p.p.", "titolo": "Provvedimenti del giudice sulla richiesta di archiviazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art409", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Fuori dei casi in cui sia stata presentata l'opposizione prevista dall'articolo 410, il giudice, se accoglie la richiesta di archiviazione, pronuncia decreto motivato e restituisce gli atti al pubblico ministero. Il provvedimento che dispone l'archiviazione e' notificato alla persona sottoposta alle indagini se nel corso del procedimento e' stata applicata nei suoi confronti la misura della custodia cautelare. 2."},
    "cpp_410": {"norma": "art. 410 c.p.p.", "titolo": "Opposizione alla richiesta di archiviazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art410", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Con l'opposizione alla richiesta di archiviazione la persona offesa dal reato chiede la prosecuzione delle indagini preliminari indicando, a pena di inammissibilita', l'oggetto della investigazione suppletiva e i relativi elementi di prova. 2. Se l'opposizione e' inammissibile e la notizia di reato e' infondata, il giudice dispone l'archiviazione con decreto motivato e restituisce gli atti al pubblico ministero."},
    "cpp_438": {"norma": "art. 438 c.p.p.", "titolo": "Presupposti del giudizio abbreviato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art438", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. L'imputato puo' chiedere che il processo sia definito all'udienza preliminare allo stato degli atti, salve le disposizioni di cui al comma 5 del presente articolo e all'articolo 441, comma 5. 1-bis. Non e' ammesso il giudizio abbreviato per i delitti puniti con la pena dell'ergastolo. 2."},
    "cpp_441": {"norma": "art. 441 c.p.p.", "titolo": "Svolgimento del giudizio abbreviato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art441", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Nel giudizio abbreviato si osservano, in quanto applicabili, le disposizioni previste per l'udienza preliminare, fatta eccezione per quelle di cui agli articoli 422 e 423. 2. La costituzione di parte civile, intervenuta dopo la conoscenza dell'ordinanza che dispone il giudizio abbreviato, equivale ad accettazione del rito abbreviato. 3."},
    "cpp_442": {"norma": "art. 442 c.p.p.", "titolo": "Decisione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art442", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Terminata la discussione, il giudice provvede a norma degli articoli 529 e seguenti. 1-bis. Ai fini della deliberazione il giudice utilizza gli atti contenuti nel fascicolo di cui all'articolo 416, comma 2, la documentazione di cui all'articolo 419, comma 3, e le prove assunte nell'udienza. 2."},
    "cpp_444": {"norma": "art. 444 c.p.p.", "titolo": "Applicazione della pena su richiesta", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art444", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. L'imputato e il pubblico ministero possono chiedere al giudice l'applicazione, nella specie e nella misura indicata, di una pena sostitutiva o di una pena pecuniaria, diminuita fino a un terzo, ovvero di una pena detentiva quando questa, tenuto conto delle circostanze e diminuita fino a un terzo, non supera cinque anni soli o congiunti a pena pecuniaria."},
    "cpp_446": {"norma": "art. 446 c.p.p.", "titolo": "Richiesta di applicazione della pena e consenso", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art446", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le parti possono formulare la richiesta prevista dall'articolo, 444, comma 1, fino alla presentazione delle conclusioni di cui agli articoli 421, comma 3, e 422, comma 3, e fino alla dichiarazione di apertura del dibattimento di primo grado nel giudizio direttissimo."},
    "cpp_448": {"norma": "art. 448 c.p.p.", "titolo": "Provvedimenti del giudice", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art448", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Nell'udienza prevista dall'articolo 447, nell'udienza preliminare, nel giudizio direttissimo e nel giudizio immediato, il giudice se ricorrono le condizioni per accogliere la richiesta prevista dall'articolo 444, comma 1, pronuncia immediatamente sentenza."},
    "cpp_459": {"norma": "art. 459 c.p.p.", "titolo": "Casi di procedimento per decreto", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art459", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Nei procedimenti per reati perseguibili di ufficio ed in quelli perseguibili a querela se questa e' stata validamente presentata e se il querelante non ha nella stessa dichiarato di opporvisi, il pubblico ministero, quando ritiene che si debba applicare soltanto una pena pecuniaria, anche se inflitta in sostituzione di una pena detentiva, puo' presentare al giudice per le indagini preliminari, entro un anno dalla […]"},
    "cpp_460": {"norma": "art. 460 c.p.p.", "titolo": "Requisiti del decreto di condanna", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art460", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il decreto di condanna contiene: a) le generalita' dell'imputato o le altre indicazioni personali che valgano a identificarlo nonche', quando occorre, quelle della persona civilmente obbligata per la pena pecuniaria; b) l'enunciazione del fatto, delle circostanze e delle disposizioni di legge violate; c) la concisa esposizione dei motivi di fatto e di diritto su cui la decisione e' fondata, comprese le ragioni […]"},
    "cpp_461": {"norma": "art. 461 c.p.p.", "titolo": "Opposizione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art461", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Nel termine di quindici giorni dalla notificazione del decreto, l'imputato e la persona civilmente obbligata per la pena pecuniaria, personalmente o a mezzo del difensore eventualmente nominato, possono proporre opposizione con le forme previste dall'articolo 582 nella cancelleria del giudice per le indagini preliminari che ha emesso il decreto ovvero nella cancelleria del tribunale o del giudice di pace del […]"},
    "cpp_464bis": {"norma": "art. 464-bis c.p.p.", "titolo": "Sospensione del procedimento con messa alla prova", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art464bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Nei casi previsti dall' articolo 168-bis del codice penale l'imputato , anche su proposta del pubblico ministero, puo' formulare richiesta di sospensione del procedimento con messa alla prova. Se il pubblico ministero formula la proposta in udienza, l'imputato puo' chiedere un termine non superiore a venti giorni per presentare la richiesta di sospensione del procedimento con messa alla prova. 2."},
    "cpp_581": {"norma": "art. 581 c.p.p.", "titolo": "Forma dell'impugnazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art581", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. L'impugnazione si propone con atto scritto nel quale sono indicati il provvedimento impugnato, la data del medesimo e il giudice che lo ha emesso, con l'enunciazione specifica, a pena di inammissibilita': a) dei capi o dei punti della decisione ai quali si riferisce l'impugnazione; b) delle prove delle quali si deduce l'inesistenza, l'omessa assunzione o l'omessa o erronea valutazione; c) delle richieste, anche […]"},
    "cpp_582": {"norma": "art. 582 c.p.p.", "titolo": "Presentazione dell'impugnazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art582", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Salvo che la legge disponga altrimenti, l'atto di impugnazione e' presentato mediante deposito con le modalita' previste dall'articolo 111- bis nella cancelleria del giudice che ha emesso il provvedimento impugnato. PERIODO SOPPRESSO DAL D.LGS. 10 OTTOBRE 2022, N. 150 . 1-bis."},
    "cpp_593": {"norma": "art. 593 c.p.p.", "titolo": "Casi di appello", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art593", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Salvo quanto previsto dagli articoli 443, comma 3, 448, comma 2, 579 e 680, l'imputato puo' appellare contro le sentenze di condanna mentre il pubblico ministero puo' appellare contro le medesime sentenze solo quando modificano il titolo del reato o escludono la sussistenza di una circostanza aggravante ad effetto speciale o stabiliscono una pena di specie diversa da quella ordinaria del reato. 2."},
    "cpp_606": {"norma": "art. 606 c.p.p.", "titolo": "Casi di ricorso", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art606", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorso per cassazione puo' essere proposto per i seguenti motivi: a) esercizio da parte del giudice di una potesta' riservata dalla legge a organi legislativi o amministrativi ovvero non consentita ai pubblici poteri; b) inosservanza o erronea applicazione della legge penale o di altre norme giuridiche, di cui si deve tener conto nell'applicazione della legge penale; c) inosservanza delle norme processuali […]"},
    "cpp_611": {"norma": "art. 611 c.p.p.", "titolo": "Procedimento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art611", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La corte provvede sui ricorsi in camera di consiglio. Se non e' diversamente stabilito e in deroga a quanto previsto dall'articolo 127, la corte giudica sui motivi, sulle richieste del procuratore generale e sulle memorie senza la partecipazione del procuratore generale e dei difensori."},
    "cpp_613": {"norma": "art. 613 c.p.p.", "titolo": "Difensori", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art613", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. l'atto di ricorso, le memorie e i motivi nuovi devono essere sottoscritti, a pena di inammissibilita', da difensori iscritti nell'albo speciale della corte di cassazione. Davanti alla corte medesima le parti sono rappresentate dai difensori. 2. Per tutti gli atti che si compiono nel procedimento davanti alla corte, il domicilio delle parti e' presso i rispettivi difensori, salvo quanto previsto dal comma 4."},
    "cpp_629": {"norma": "art. 629 c.p.p.", "titolo": "Condanne soggette a revisione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art629", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. E' ammessa in ogni tempo a favore dei condannati, nei casi determinati dalla legge, la revisione delle sentenze di condanna o delle sentenze emesse ai sensi dell'articolo 444, comma 2, o dei decreti penali di condanna, divenuti irrevocabili, anche se la pena e' gia' stata eseguita o e' estinta."},
    "cpp_629bis": {"norma": "art. 629-bis c.p.p.", "titolo": "Rescissione del giudicato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art629bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Fuori dei casi disciplinati dall'articolo 628-bis, il condannato o la persona sottoposta a misura di sicurezza con sentenza passata in giudicato nei cui confronti si sia proceduto in assenza puo' ottenere la rescissione del giudicato qualora provi che sia stato dichiarato assente in mancanza dei presupposti previsti dall'articolo 420-bis, e che non abbia potuto proporre impugnazione della sentenza nei termini […]"},
    "cpp_630": {"norma": "art. 630 c.p.p.", "titolo": "Casi di revisione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art630", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La revisione puo' essere richiesta: a) se i fatti stabiliti a fondamento della sentenza o del decreto penale di condanna non possono conciliarsi con quelli stabiliti in un'altra sentenza penale irrevocabile del giudice ordinario o di un giudice speciale; b) se la sentenza o il decreto penale di condanna hanno ritenuto la sussistenza del reato a carico del condannato in conseguenza di una sentenza del giudice […]"},
    "cpp_633": {"norma": "art. 633 c.p.p.", "titolo": "Forma della richiesta", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art633", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La richiesta di revisione e' proposta personalmente o per mezzo di un procuratore speciale. Essa deve contenere l'indicazione specifica delle ragioni e delle prove che la giustificano e deve essere presentata, unitamente a eventuali atti e documenti, nella cancelleria della corte di appello individuata secondo i criteri di cui all'articolo 11 2."},
    "cpp_656": {"norma": "art. 656 c.p.p.", "titolo": "Esecuzione delle pene detentive", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art656", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Quando deve essere eseguita una sentenza di condanna a pena detentiva, il pubblico ministero emette ordine di esecuzione con il quale, se il condannato non e' detenuto, ne dispone la carcerazione. Copia dell'ordine e' consegnata all'interessato. 2. Se il condannato e' gia' detenuto, l'ordine di esecuzione e' comunicato al Ministro di grazia e giustizia e notificato all'interessato. 3."},
    "cpp_666": {"norma": "art. 666 c.p.p.", "titolo": "Procedimento di esecuzione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art666", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il giudice dell'esecuzione procede a richiesta del pubblico ministero, dell'interessato o del difensore. 2. Se la richiesta appare manifestamente infondata per difetto delle condizioni di legge ovvero costituisce mera riproposizione di una richiesta gia' rigettata, basata sui medesimi elementi, il giudice o il presidente del collegio, sentito il pubblico ministero, la dichiara inammissibile con decreto motivato, […]"},
    "cpp_667": {"norma": "art. 667 c.p.p.", "titolo": "Dubbio sull'identita' fisica della persona detenuta", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1988-09-22;447~art667", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Se vi e' ragione di dubitare dell'identita' della persona arrestata per esecuzione di pena o perche' evasa mentre scontava una condanna, il giudice dell'esecuzione la interroga e compie ogni indagine utile alla sua identificazione anche a mezzo della polizia giudiziaria. 2. Quando riconosce che non si tratta della persona nei cui confronti deve compiersi l'esecuzione, ne ordina immediatamente la liberazione."},
    "dispattcc_63": {"norma": "art. 63 disp. att. c.c.", "titolo": "Articolo 63", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-30;318~art63", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Per la riscossione dei contributi in base allo stato di ripartizione approvato dall'assemblea, l'amministratore, senza bisogno di autorizzazione di questa, puo' ottenere un decreto di ingiunzione immediatamente esecutivo, nonostante opposizione, ed e' tenuto a comunicare ai creditori non ancora soddisfatti che lo interpellino i dati dei condomini morosi."},
    "dlgs150_art10": {"norma": "art. 10 D.Lgs. 150/2011", "titolo": "Delle controversie in materia di applicazione delle disposizioni in materia di protezione dei dati personali", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2011-09-01;150~art10", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le controversie previste dall' articolo 152 del decreto legislativo 30 giugno 2003, n. 196 , sono regolate dal rito del lavoro, ove non diversamente disposto dal presente articolo. 2. Sono competenti, in via alternativa, il tribunale del luogo in cui il titolare del trattamento risiede o ha sede ovvero il tribunale del luogo di residenza dell'interessato. 3."},
    "dlgs150_art14": {"norma": "art. 14 D.Lgs. 150/2011", "titolo": "Delle controversie in materia di liquidazione degli onorari e dei diritti di avvocato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2011-09-01;150~art14", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le controversie previste dall' articolo 28 della legge 13 giugno 1942, n. 794 , e l'opposizione proposta a norma dell' articolo 645 del codice di procedura civile contro il decreto ingiuntivo riguardante onorari, diritti o spese spettanti ad avvocati per prestazioni giudiziali sono regolate dal rito semplificato di cognizione, ove non diversamente disposto dal presente articolo. 2."},
    "dlgs150_art15": {"norma": "art. 15 D.Lgs. 150/2011", "titolo": "Dell'opposizione a decreto di pagamento di spese di giustizia", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2011-09-01;150~art15", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le controversie previste dall' articolo 170 del decreto del Presidente della Repubblica 30 maggio 2002, n. 115 , sono regolate dal rito semplificato di cognizione, ove non diversamente disposto dal presente articolo. 2. Il ricorso e' proposto al capo dell'ufficio giudiziario cui appartiene il magistrato che ha emesso il provvedimento impugnato."},
    "dlgs150_art18": {"norma": "art. 18 D.Lgs. 150/2011", "titolo": "Delle controversie in materia di espulsione dei cittadini di Stati che non sono membri dell'Unione europea", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2011-09-01;150~art18", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le controversie aventi ad oggetto l'impugnazione del decreto di espulsione pronunciato dal prefetto ai sensi del decreto legislativo 25 luglio 1998, n. 286 , sono regolate dal rito semplificato di cognizione, ove non diversamente disposto dal presente articolo. 2. E' competente il giudice di pace del luogo in cui ha sede l'autorita' che ha disposto l'espulsione. 3."},
    "dlgs150_art20": {"norma": "art. 20 D.Lgs. 150/2011", "titolo": "Articolo 20", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2011-09-01;150~art20", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Dell'opposizione al diniego del nulla osta al ricongiungimento familiare e del permesso di soggiorno per motivi familiari, nonche' agli altri provvedimenti dell'autorita' amministrativa in materia di diritto all'unita' familiare 1. Le controversie previste dall' articolo 30, comma 6, del decreto legislativo 25 luglio 1998, n."},
    "dlgs150_art28": {"norma": "art. 28 D.Lgs. 150/2011", "titolo": "Delle controversie in materia di discriminazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2011-09-01;150~art28", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le controversie in materia di discriminazione di cui all' articolo 44 del decreto legislativo 25 luglio 1998, n. 286 , quelle di cui all' articolo 4 del decreto legislativo 9 luglio 2003, n. 215 , quelle di cui all' articolo 4 del decreto legislativo 9 luglio 2003, n. 216 , quelle di cui all' articolo 3 della legge 1° marzo 2006, n."},
    "dlgs150_art6": {"norma": "art. 6 D.Lgs. 150/2011", "titolo": "Dell'opposizione ad ordinanza-ingiunzione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2011-09-01;150~art6", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le controversie previste dall' articolo 22 della legge 24 novembre 1981, n. 689 , sono regolate dal rito del lavoro, ove non diversamente stabilito dalle disposizioni del presente articolo. 2. L'opposizione si propone davanti al giudice del luogo in cui e' stata commessa la violazione. 3."},
    "dlgs168_art3": {"norma": "art. 3 D.Lgs. 168/2003", "titolo": "Competenza per materia delle sezioni specializzate", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2003-06-27;168~art3", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le sezioni specializzate sono competenti in materia di: a) controversie di cui all' articolo 134 del decreto legislativo 10 febbraio 2005, n. 30, e successive modificazioni, ad esclusione delle azioni di merito e cautelari per le quali l'Accordo su un tribunale unificato dei brevetti, fatto a Bruxelles il 19 febbraio 2013, pubblicato nella Gazzetta Ufficiale dell'Unione europea C 175 del 20 giugno 2013, prevede […]"},
    "dlgs23_art1": {"norma": "art. 1 D.Lgs. 23/2015", "titolo": "Campo di applicazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2015-03-04;23~art1", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Per i lavoratori che rivestono la qualifica di operai, impiegati o quadri, assunti con contratto di lavoro subordinato a tempo indeterminato a decorrere dalla data di entrata in vigore del presente decreto, il regime di tutela nel caso di licenziamento illegittimo e' disciplinato dalle disposizioni di cui al presente decreto. 2."},
    "dlgs23_art3": {"norma": "art. 3 D.Lgs. 23/2015", "titolo": "Licenziamento per giustificato motivo e giusta causa", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2015-03-04;23~art3", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Salvo quanto disposto dal comma 2, nei casi in cui risulta accertato che non ricorrono gli estremi del licenziamento per giustificato motivo oggettivo o per giustificato motivo soggettivo o giusta causa, il giudice dichiara estinto il rapporto di lavoro alla data del licenziamento e condanna il datore di lavoro al pagamento di un'indennita' non assoggettata a contribuzione previdenziale di importo pari a due […]"},
    "dlgs25_art35": {"norma": "art. 35 D.Lgs. 25/2008", "titolo": "Impugnazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2008-01-28;25~art35", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Avverso i provvedimenti adottati dalla Commissione territoriale e avverso i provvedimenti adottati dalla Commissione nazionale e' ammesso ricorso all'autorita' giudiziaria ordinaria."},
    "dlgs25_art35bis": {"norma": "art. 35-bis D.Lgs. 25/2008", "titolo": "Delle controversie in materia di riconoscimento della protezione internazionale", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2008-01-28;25~art35bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le controversie aventi ad oggetto l'impugnazione dei provvedimenti previsti dall'articolo 35 anche per mancato riconoscimento dei presupposti per la protezione speciale a norma dell'articolo 32, comma 3, sono regolate dalle disposizioni di cui agli articoli 737 e seguenti del codice di procedura civile, ove non diversamente disposto dal presente articolo e, quanto alle procedure di frontiera, dall'articolo […]"},
    "dlgs274_art21": {"norma": "art. 21 D.Lgs. 274/2000", "titolo": "Ricorso immediato al giudice", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2000-08-28;274~art21", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Per i reati procedibili a querela e' ammessa la citazione a giudizio dinanzi al giudice di pace della persona alla quale il reato e' attribuito su ricorso della persona offesa. 2."},
    "dlgs274_art22": {"norma": "art. 22 D.Lgs. 274/2000", "titolo": "Presentazione del ricorso", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2000-08-28;274~art22", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorso, previamente comunicato al pubblico ministero mediante deposito di copia presso la sua segreteria, e' presentato, a cura del ricorrente, con la prova dell'avvenuta comunicazione, nella cancelleria del giudice di pace competente per territorio nel termine di tre mesi dalla notizia del fatto che costituisce reato. 2."},
    "dlgs28_art5bis": {"norma": "art. 5-bis D.Lgs. 28/2010", "titolo": "Procedimento di opposizione a decreto ingiuntivo", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2010-03-04;28~art5bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Quando l'azione di cui all'articolo 5, comma 1, e' stata introdotta con ricorso per decreto ingiuntivo, nel procedimento di opposizione l'onere di presentare la domanda di mediazione grava sulla parte che ha proposto ricorso per decreto ingiuntivo."},
    "dlgs546_art12": {"norma": "art. 12 D.Lgs. 546/1992", "titolo": "Assistenza tecnica", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art12", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le parti, diverse dagli enti impositori, dagli agenti della riscossione e dai soggetti iscritti nell'albo di cui all' articolo 53 del decreto legislativo 15 dicembre 1997, n. 446 , devono essere assistite in giudizio da un difensore abilitato. 2. Per le controversie di valore fino a tremila euro le parti possono stare in giudizio senza assistenza tecnica."},
    "dlgs546_art18": {"norma": "art. 18 D.Lgs. 546/1992", "titolo": "Il ricorso", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art18", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il processo e' introdotto con ricorso alla corte di giustizia tributaria di primo grado . 2. Il ricorso deve contenere l'indicazione: a) della corte di giustizia tributaria di primo e secondo grado cui e' diretto; b) del ricorrente e del suo legale rappresentante, della relativa residenza o sede legale o del domicilio eventualmente eletto nel territorio dello Stato, nonche' del codice fiscale e dell'indirizzo di […]"},
    "dlgs546_art19": {"norma": "art. 19 D.Lgs. 546/1992", "titolo": "Atti impugnabili e oggetto del ricorso", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art19", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorso puo' essere proposto avverso: a) l'avviso di accertamento del tributo; b) l'avviso di liquidazione del tributo; c) il provvedimento che irroga le sanzioni; d) il ruolo e la cartella di pagamento; e) l'avviso di mora; e-bis) l'iscrizione di ipoteca sugli immobili di cui all' articolo 77 del decreto del Presidente della Repubblica 29 settembre 1973, n."},
    "dlgs546_art21": {"norma": "art. 21 D.Lgs. 546/1992", "titolo": "Termine per la proposizione del ricorso", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art21", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorso deve essere proposto a pena di inammissibilita' entro sessanta giorni dalla data di notificazione dell'atto impugnato. La notificazione della cartella di pagamento vale anche come notificazione del ruolo. 2."},
    "dlgs546_art22": {"norma": "art. 22 D.Lgs. 546/1992", "titolo": "Costituzione in giudizio del ricorrente", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art22", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorrente, entro trenta giorni dalla proposizione del ricorso, a pena d'inammissibilita' deposita, nella segreteria della corte di giustizia tributaria di primo e secondo grado adita, o trasmette a mezzo posta, in plico raccomandato senza busta con avviso di ricevimento, l'originale del ricorso notificato a norma degli articoli 137 e seguenti del codice di procedura civile ovvero copia del ricorso consegnato […]"},
    "dlgs546_art38": {"norma": "art. 38 D.Lgs. 546/1992", "titolo": "Richiesta di copie e notificazione della sentenza", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art38", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Ciascuna parte puo' richiedere alla segreteria copie autentiche della sentenza e la segreteria e' tenuta a rilasciarle entro cinque giorni dalla richiesta, previa corresponsione delle spese. 2."},
    "dlgs546_art47": {"norma": "art. 47 D.Lgs. 546/1992", "titolo": "Sospensione dell'atto impugnato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art47", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorrente, se dall'atto impugnato puo' derivargli un danno grave ed irreparabile, puo' chiedere alla corte di giustizia tributaria di primo o di secondo grado presso la quale e' pendente il giudizio, ovvero adita ai sensi dell'articolo 62-bis la sospensione dell'esecuzione dell'atto stesso con istanza motivata proposta nel ricorso o con atto separato notificata alle altre parti e depositato in segreteria […]"},
    "dlgs546_art48": {"norma": "art. 48 D.Lgs. 546/1992", "titolo": "Conciliazione fuori udienza", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art48", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Se in pendenza del giudizio le parti raggiungono un accordo conciliativo, presentano istanza congiunta sottoscritta personalmente o dai difensori per la definizione totale o parziale della controversia. 2. Se la data di trattazione e' gia' fissata e sussistono le condizioni di ammissibilita', la corte di giustizia tributaria pronuncia sentenza di cessazione della materia del contendere."},
    "dlgs546_art48bis": {"norma": "art. 48-bis D.Lgs. 546/1992", "titolo": "Conciliazione in udienza", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art48bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Ciascuna parte entro il termine di cui all'articolo 32, comma 2, puo' presentare istanza per la conciliazione totale o parziale della controversia. 2. All'udienza la commissione, se sussistono le condizioni di ammissibilita', invita le parti alla conciliazione rinviando eventualmente la causa alla successiva udienza per il perfezionamento dell'accordo conciliativo. 3."},
    "dlgs546_art51": {"norma": "art. 51 D.Lgs. 546/1992", "titolo": "Termini d'impugnazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art51", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Se la legge non dispone diversamente il termine per impugnare la sentenza della corte di giustizia tributaria di primo e secondo grado e' di sessanta giorni, decorrente dalla sua notificazione ad istanza di parte, salvo quanto disposto dall'art. 38, comma 3. 2. Nel caso di revocazione per i motivi di cui ai numeri 1 , 2 , 3 e 6 dell'art."},
    "dlgs546_art52": {"norma": "art. 52 D.Lgs. 546/1992", "titolo": "Giudice competente e provvedimenti sull'esecuzione provvisoria in appello", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art52", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La sentenza della corte di giustizia tributaria di primo grado puo' essere appellata alla corte di giustizia tributaria di secondo grado competente a norma dell'articolo 4, comma 2. 2. L'appellante puo' chiedere alla corte di giustizia tributaria di secondo grado di sospendere in tutto o in parte l'esecutivita' della sentenza impugnata, se sussistono gravi e fondati motivi. PERIODO SOPPRESSO DAL D.LGS."},
    "dlgs546_art53": {"norma": "art. 53 D.Lgs. 546/1992", "titolo": "Forma dell'appello", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art53", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorso in appello contiene l'indicazione della corte di giustizia tributaria di primo e secondo grado a cui e' diretto, dell'appellante e delle altre parti nei cui confronti e' proposto, gli estremi della sentenza impugnata, l'esposizione sommaria dei fatti, l'oggetto della domanda ed i motivi specifici dell'impugnazione."},
    "dlgs546_art62": {"norma": "art. 62 D.Lgs. 546/1992", "titolo": "Norme applicabili", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art62", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Avverso la sentenza della corte di giustizia tributaria di secondo grado puo' essere proposto ricorso per cassazione per i motivi di cui ai numeri da 1 a 5 dell'art. 360, primo comma, del codice di procedura civile . 2. Al ricorso per cassazione ed al relativo procedimento si applicano le norme dettate dal codice di procedura civile in quanto compatibili con quelle del presente decreto. 2-bis."},
    "dlgs546_art70": {"norma": "art. 70 D.Lgs. 546/1992", "titolo": "Giudizio di ottemperanza", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1992-12-31;546~art70", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La parte che vi ha interesse puo' richiedere l'ottemperanza agli obblighi derivanti dalla sentenza della corte di giustizia tributaria di primo e secondo grado passata in giudicato mediante ricorso da depositare in doppio originale alla segreteria della corte di giustizia tributaria di primo grado, qualora la sentenza passata in giudicato sia stata da essa pronunciata, e in ogni altro caso alla segreteria della […]"},
    "dlgs81_art19": {"norma": "art. 19 D.Lgs. 81/2015", "titolo": "Apposizione del termine e durata massima", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2015-06-15;81~art19", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Al contratto di lavoro subordinato puo' essere apposto un termine di durata non superiore a dodici mesi. Il contratto puo' avere una durata superiore, ma comunque non eccedente i ventiquattro mesi, solo in presenza di almeno una delle seguenti condizioni: a) nei casi previsti dai contratti collettivi di cui all'articolo 51; b) in assenza delle previsioni di cui alla lettera a), nei contratti collettivi applicati […]"},
    "dlgs81_art21": {"norma": "art. 21 D.Lgs. 81/2015", "titolo": "Proroghe e rinnovi", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2015-06-15;81~art21", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il contratto puo' essere prorogato e rinnovato liberamente nei primi dodici mesi e, successivamente, solo in presenza delle condizioni di cui all'articolo 19, comma 1. In caso di violazione di quanto disposto dal primo periodo, il contratto si trasforma in contratto a tempo indeterminato."},
    "dlgs81_art28": {"norma": "art. 28 D.Lgs. 81/2015", "titolo": "Decadenza e tutele", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2015-06-15;81~art28", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. L'impugnazione del contratto a tempo determinato deve avvenire, con le modalita' previste dal primo comma dell'articolo 6 della legge 15 luglio 1966, n. 604 , entro centottanta giorni dalla cessazione del singolo contratto. Trova altresi' applicazione il secondo comma del suddetto articolo 6. 2."},
    "dlgs81_art38": {"norma": "art. 38 D.Lgs. 81/2015", "titolo": "Somministrazione irregolare", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2015-06-15;81~art38", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. In mancanza di forma scritta il contratto di somministrazione di lavoro e' nullo e i lavoratori sono considerati a tutti gli effetti alle dipendenze dell'utilizzatore. 2."},
    "dlgs81_art41": {"norma": "art. 41 D.Lgs. 81/2015", "titolo": "Definizione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2015-06-15;81~art41", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. L'apprendistato e' un contratto di lavoro a tempo indeterminato finalizzato alla formazione e alla occupazione dei giovani. 2. Il contratto di apprendistato si articola nelle seguenti tipologie: a) apprendistato per la qualifica e il diploma professionale, il diploma di istruzione secondaria superiore e il certificato di specializzazione tecnica superiore; b) apprendistato professionalizzante; c) apprendistato di […]"},
    "dlgs81_art42": {"norma": "art. 42 D.Lgs. 81/2015", "titolo": "Disciplina generale", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2015-06-15;81~art42", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il contratto di apprendistato e' stipulato in forma scritta ai fini della prova. Il contratto di apprendistato contiene, in forma sintetica, il piano formativo individuale definito anche sulla base di moduli e formulari stabiliti dalla contrattazione collettiva o dagli enti bilaterali di cui all' articolo 2, comma 1, lettera h), del decreto legislativo n. 276 del 2003 ."},
    "dpr115_art170": {"norma": "art. 170 D.P.R. 115/2002", "titolo": "Opposizione al decreto di pagamento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:2002-05-30;115~art170", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Avverso il decreto di pagamento emesso a favore dell'ausiliario del magistrato, del custode e delle imprese private cui e' affidato l'incarico di demolizione e riduzione in pristino, il beneficiario e le parti processuali, compreso il pubblico ministero, possono proporre opposizione. L'opposizione e' disciplinata dall' articolo 15 del decreto legislativo 1° settembre 2011, n. 150 . 2. COMMA ABROGATO DAL D.LGS."},
    "dpr115_art82": {"norma": "art. 82 D.P.R. 115/2002", "titolo": "Onorario e spese del difensore", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:2002-05-30;115~art82", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. L'onorario e le spese spettanti al difensore sono liquidati dall'autorita' giudiziaria con decreto di pagamento, osservando la tariffa professionale in modo che, in ogni caso, non risultino superiori ai valori medi delle tariffe professionali vigenti relative ad onorari, diritti ed indennita', tenuto conto della natura dell'impegno professionale, in relazione all'incidenza degli atti assunti rispetto alla […]"},
    "dpr115_art84": {"norma": "art. 84 D.P.R. 115/2002", "titolo": "Opposizione al decreto di pagamento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:2002-05-30;115~art84", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Avverso il decreto di pagamento del compenso al difensore, all'ausiliario del magistrato e al consulente tecnico di parte, e' ammessa opposizione ai sensi dell'articolo 170."},
    "dpr1199_art2": {"norma": "art. 2 D.P.R. 1199/1971", "titolo": "Termine - Presentazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.del.presidente.della.repubblica:1971-11-24;1199~art2", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il ricorso deve essere proposto nel termine di trenta giorni dalla data della notificazione o della comunicazione in via amministrativa dell'atto impugnato o da quando l'interessato ne abbia avuto piena conoscenza."},
    "gdpr_art12": {"norma": "art. 12 Reg. (UE) 2016/679", "titolo": "Informazioni, comunicazioni e modalità trasparenti per l'esercizio dei diritti dell'interessato", "url": "https://eur-lex.europa.eu/eli/reg/2016/679/oj", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il titolare del trattamento adotta misure appropriate per fornire all'interessato tutte le informazioni di cui agli articoli 13 e 14 e le comunicazioni di cui agli articoli da 15 a 22 e all'articolo 34 relative al trattamento in forma concisa, trasparente, intelligibile e facilmente accessibile, con un linguaggio semplice e chiaro, in particolare nel caso di informazioni destinate specificamente ai minori."},
    "gdpr_art15": {"norma": "art. 15 Reg. (UE) 2016/679", "titolo": "Diritto di accesso dell'interessato", "url": "https://eur-lex.europa.eu/eli/reg/2016/679/oj", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. L'interessato ha il diritto di ottenere dal titolare del trattamento la conferma che sia o meno in corso un trattamento di dati personali che lo riguardano e in tal caso, di ottenere l'accesso ai dati personali e alle seguenti informazioni: a) le finalità del trattamento; b) le categorie di dati personali in questione; c) i destinatari o le categorie di destinatari a cui i dati personali sono stati o saranno […]"},
    "gdpr_art17": {"norma": "art. 17 Reg. (UE) 2016/679", "titolo": "Diritto alla cancellazione («diritto all'oblio»)", "url": "https://eur-lex.europa.eu/eli/reg/2016/679/oj", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. L'interessato ha il diritto di ottenere dal titolare del trattamento la cancellazione dei dati personali che lo riguardano senza ingiustificato ritardo e il titolare del trattamento ha l'obbligo di cancellare senza ingiustificato ritardo i dati personali, se sussiste uno dei motivi seguenti: a) i dati personali non sono più necessari rispetto alle finalità per le quali sono stati raccolti o altrimenti trattati; […]"},
    "gdpr_art77": {"norma": "art. 77 Reg. (UE) 2016/679", "titolo": "Diritto di proporre reclamo all'autorità di controllo", "url": "https://eur-lex.europa.eu/eli/reg/2016/679/oj", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Fatto salvo ogni altro ricorso amministrativo o giurisdizionale, l'interessato che ritenga che il trattamento che lo riguarda violi il presente regolamento ha il diritto di proporre reclamo a un'autorità di controllo, segnatamente nello Stato membro in cui risiede abitualmente, lavora oppure del luogo ove si è verificata la presunta violazione. 2."},
    "gdpr_art78": {"norma": "art. 78 Reg. (UE) 2016/679", "titolo": "Diritto a un ricorso giurisdizionale effettivo nei confronti dell'autorità di controllo", "url": "https://eur-lex.europa.eu/eli/reg/2016/679/oj", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Fatto salvo ogni altro ricorso amministrativo o extragiudiziale, ogni persona fisica o giuridica ha il diritto di proporre un ricorso giurisdizionale effettivo avverso una decisione giuridicamente vincolante dell'autorità di controllo che la riguarda. 2."},
    "gdpr_art79": {"norma": "art. 79 Reg. (UE) 2016/679", "titolo": "Diritto a un ricorso giurisdizionale effettivo nei confronti del titolare del trattamento o del responsabile del trattamento", "url": "https://eur-lex.europa.eu/eli/reg/2016/679/oj", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Fatto salvo ogni altro ricorso amministrativo o extragiudiziale disponibile, compreso il diritto di proporre reclamo a un'autorità di controllo ai sensi dell'articolo 77, ogni interessato ha il diritto di proporre un ricorso giurisdizionale effettivo qualora ritenga che i diritti di cui gode a norma del presente regolamento siano stati violati a seguito di un trattamento. 2."},
    "gdpr_art82": {"norma": "art. 82 Reg. (UE) 2016/679", "titolo": "Diritto al risarcimento e responsabilità", "url": "https://eur-lex.europa.eu/eli/reg/2016/679/oj", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Chiunque subisca un danno materiale o immateriale causato da una violazione del presente regolamento ha il diritto di ottenere il risarcimento del danno dal titolare del trattamento o dal responsabile del trattamento. 2. Un titolare del trattamento coinvolto nel trattamento risponde per il danno cagionato dal suo trattamento che violi il presente regolamento."},
    "l247_art17": {"norma": "art. 17 L. 247/2012", "titolo": "Iscrizione e cancellazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2012-12-31;247~art17", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Costituiscono requisiti per l'iscrizione all'albo: a) essere cittadino italiano o di Stato appartenente all'Unione europea, salvo quanto previsto dal comma 2 per gli stranieri cittadini di uno Stato non appartenente all'Unione europea; b) avere superato l'esame di abilitazione; c) avere il domicilio professionale nel circondario del tribunale ove ha sede il consiglio dell'ordine; d) godere del pieno esercizio dei […]"},
    "l247_art29": {"norma": "art. 29 L. 247/2012", "titolo": "Compiti e prerogative del consiglio", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2012-12-31;247~art29", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il consiglio: a) provvede alla tenuta degli albi, degli elenchi e dei registri; b) approva i regolamenti interni, i regolamenti in materie non disciplinate dal CNF e quelli previsti come integrazione ad essi; c) sovraintende al corretto ed efficace esercizio del tirocinio forense."},
    "l247_art36": {"norma": "art. 36 L. 247/2012", "titolo": "Competenza giurisdizionale", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2012-12-31;247~art36", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il CNF pronuncia sui reclami avverso i provvedimenti disciplinari nonche' in materia di albi, elenchi e registri e rilascio di certificato di compiuta pratica; pronuncia sui ricorsi relativi alle elezioni dei consigli dell'ordine; risolve i conflitti di competenza tra ordini circondariali; esercita le funzioni disciplinari nei confronti dei propri componenti, quando il consiglio distrettuale di disciplina […]"},
    "l247_art50": {"norma": "art. 50 L. 247/2012", "titolo": "Consigli distrettuali di disciplina", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2012-12-31;247~art50", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il potere disciplinare appartiene ai consigli distrettuali di disciplina forense. 2. Il consiglio distrettuale di disciplina e' composto da membri eletti su base capitaria e democratica, con il rispetto della rappresentanza di genere di cui all' articolo 51 della Costituzione , secondo il regolamento approvato dal CNF."},
    "l247_art61": {"norma": "art. 61 L. 247/2012", "titolo": "Impugnazioni", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2012-12-31;247~art61", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Avverso le decisioni del consiglio distrettuale di disciplina e' ammesso ricorso, entro trenta giorni dal deposito della sentenza, avanti ad apposita sezione disciplinare del CNF da parte dell'incolpato, nel caso di affermazione di responsabilita', e, per ogni decisione, da parte del consiglio dell'ordine presso cui l'incolpato e' iscritto, del procuratore della Repubblica e del procuratore generale del distretto […]"},
    "l300_art18": {"norma": "art. 18 L. 300/1970", "titolo": "Articolo 18", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1970-05-20;300~art18", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Tutela del lavoratore in caso di licenziamento illegittimo Il giudice, con la sentenza con la quale dichiara la nullita' del licenziamento perche' discriminatorio ai sensi dell' articolo 3 della legge 11 maggio 1990, n. 108 , ovvero intimato in concomitanza col matrimonio ai sensi dell' articolo 35 del codice delle pari opportunita' tra uomo e donna , di cui al decreto legislativo 11 aprile 2006, n."},
    "l300_art28": {"norma": "art. 28 L. 300/1970", "titolo": "Repressione della condotta antisindacale", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1970-05-20;300~art28", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Qualora il datore di lavoro ponga in essere comportamenti diretti ad impedire o limitare l'esercizio della liberta' e della attivita' sindacale nonche' del diritto di sciopero, su ricorso degli organismi locali delle associazioni sindacali nazionali che vi abbiano interesse, il pretore del luogo ove e' posto in essere il comportamento denunziato, nei due giorni successivi, convocate le parti ed assunte sommarie […]"},
    "l300_art7": {"norma": "art. 7 L. 300/1970", "titolo": "Sanzioni disciplinari", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1970-05-20;300~art7", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Le norme disciplinari relative alle sanzioni, alle infrazioni in relazione alle quali ciascuna di esse puo' essere applicata ed alle procedure di contestazione delle stesse, devono essere portate a conoscenza dei lavoratori mediante affissione in luogo accessibile a tutti. Esse devono applicare quanto in materia e' stabilito da accordi e contratti di lavoro ove esistano."},
    "l354_art47": {"norma": "art. 47 L. 354/1975", "titolo": "Affidamento in prova al servizio sociale", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1975-07-26;354~art47", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Se la pena detentiva inflitta non supera tre anni, il condannato puo' essere affidato al servizio sociale fuori dell'istituto per un periodo uguale a quello della pena da scontare. 2."},
    "l354_art47ter": {"norma": "art. 47-ter L. 354/1975", "titolo": "Detenzione domiciliare", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1975-07-26;354~art47ter", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "01. La pena della reclusione per qualunque reato, ad eccezione di quelli previsti dal libro II, titolo XII, capo III, sezione I, e dagli articoli 609-bis , 609-quater e 609-octies del codice penale , dall' articolo 51, comma 3-bis, del codice di procedura penale e dall'articolo 4-bis della presente legge, puo' essere espiata nella propria abitazione o in altro luogo pubblico di cura, assistenza ed accoglienza, […]"},
    "l354_art50": {"norma": "art. 50 L. 354/1975", "titolo": "Ammissione alla semiliberta'", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1975-07-26;354~art50", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Possono essere espiate in regime di semiliberta' la pena dell'arresto e la pena della reclusione non superiore a sei mesi, se il condannato non e' affidato in prova al servizio sociale. 2."},
    "l392_art27": {"norma": "art. 27 L. 392/1978", "titolo": "Durata della locazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1978-07-27;392~art27", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "La durata delle locazioni e sublocazioni di immobili urbani non puo' essere inferiore a sei anni se gli immobili sono adibiti ad una delle attivita' appresso indicate industriali, commerciali e artigianali di interesse turistico, quali agenzie di viaggio e turismo, impianti sportivi e ricreativi, aziende di soggiorno ed altri organismi di promozione turistica e simili."},
    "l392_art28": {"norma": "art. 28 L. 392/1978", "titolo": "Rinnovazione del contratto", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1978-07-27;392~art28", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Per le locazioni di immobili nei quali siano esercitate le attivita' indicate nei commi primo e secondo dell'articolo 27, il contratto si rinnova tacitamente di sei anni in sei anni e, per quelle di immobili adibiti ad attivita' alberghiere o all'esercizio di attivita' teatrali , di nove anni in nove anni; tale rinnovazione non ha luogo se sopravviene disdetta da comunicarsi all'altra parte, a mezzo di lettera […]"},
    "l392_art29": {"norma": "art. 29 L. 392/1978", "titolo": "Diniego di rinnovazione del contratto alla prima scadenza", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1978-07-27;392~art29", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il diniego della rinnovazione del contratto alla prima scadenza di cui all'articolo precedente e' consentito al locatore ove egli intenda: a) adibire l'immobile ad abitazione propria o del coniuge o dei parenti entro il secondo grado in linea retta; b) adibire l'immobile all'esercizio, in proprio o da parte del coniuge o dei parenti entro il secondo grado in linea retta, di una delle attivita' indicate nell'articolo […]"},
    "l392_art34": {"norma": "art. 34 L. 392/1978", "titolo": "Indennita' per la perdita dell'avviamento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1978-07-27;392~art34", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "In caso di cessazione del rapporto di locazione relativo agli immobili di cui all'articolo 27, che non sia dovuta a risoluzione per inadempimento o disdetta o recesso del conduttore o a una delle procedure previste dal regio decreto 16 marzo 1942, n."},
    "l392_art35": {"norma": "art. 35 L. 392/1978", "titolo": "Limiti", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1978-07-27;392~art35", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Le disposizioni di cui all'articolo precedente non si applicano in caso di cessazione di rapporti di locazione relativi ad immobili utilizzati per lo svolgimento di attivita' che non comportino contatti diretti con il pubblico degli utenti e dei consumatori nonche' destinati all'esercizio di attivita' professionali, ad attivita' di carattere transitorio, ed agli immobili complementari o interni a stazioni […]"},
    "l392_art79": {"norma": "art. 79 L. 392/1978", "titolo": "Patti contrari alla legge", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1978-07-27;392~art79", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "E' nulla ogni pattuizione diretta a limitare la durata legale del contratto o ad attribuire al locatore un canone maggiore rispetto a quello previsto dagli articoli precedenti ovvero ad attribuirgli altro vantaggio in contrasto con le disposizioni della presente legge."},
    "l49_art1": {"norma": "art. 1 L. 49/2023", "titolo": "Definizione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2023-04-21;49~art1", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Ai fini della presente legge, per equo compenso si intende la corresponsione di un compenso proporzionato alla quantita' e alla qualita' del lavoro svolto, al contenuto e alle caratteristiche della prestazione professionale, nonche' conforme ai compensi previsti rispettivamente: a) per gli avvocati, dal decreto del Ministro della giustizia emanato ai sensi dell' articolo 13, comma 6, della legge 31 dicembre 2012, […]"},
    "l49_art2": {"norma": "art. 2 L. 49/2023", "titolo": "Ambito di applicazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2023-04-21;49~art2", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La presente legge si applica ai rapporti professionali aventi ad oggetto la prestazione d'opera intellettuale di cui all' articolo 2230 del codice civile regolati da convenzioni aventi ad oggetto lo svolgimento, anche in forma associata o societaria, delle attivita' professionali svolte in favore di imprese bancarie e assicurative nonche' delle loro societa' controllate, delle loro mandatarie e delle imprese che […]"},
    "l49_art3": {"norma": "art. 3 L. 49/2023", "titolo": "Nullita' delle clausole che prevedono un compenso non equo l", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2023-04-21;49~art3", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Sono nulle le clausole che non prevedono un compenso equo e proporzionato all'opera prestata, tenendo conto a tale fine anche dei costi sostenuti dal prestatore d'opera; sono tali le pattuizioni di un compenso inferiore agli importi stabiliti dai parametri per la liquidazione dei compensi dei professionisti iscritti agli ordini o ai collegi professionali, fissati con decreto ministeriale, o ai parametri determinati […]"},
    "l49_art5": {"norma": "art. 5 L. 49/2023", "titolo": "Disciplina dell'equo compenso", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2023-04-21;49~art5", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Gli accordi preparatori o definitivi, purche' vincolanti per il professionista, conclusi tra i professionisti e le imprese di cui all'articolo 2 si presumono unilateralmente predisposti dalle imprese stesse, salva prova contraria. 2."},
    "l49_art7": {"norma": "art. 7 L. 49/2023", "titolo": "Parere di congruita' con efficacia di titolo esecutivo", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2023-04-21;49~art7", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. In alternativa alle procedure di cui agli articoli 633 e seguenti del codice di procedura civile e di cui all' articolo 14 del decreto legislativo 1° settembre 2011, n."},
    "l604_art10": {"norma": "art. 10 L. 604/1966", "titolo": "Articolo 10", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1966-07-15;604~art10", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Le norme della presente legge si applicano nei confronti dei prestatori di lavoro che rivestano la qualifica di impiegato e di operaio, ai sensi dell' articolo 2095 del Codice civile e, per quelli assunti in prova, si applicano dal momento in cui l'assunzione diviene definitiva e, in ogni caso, quando sono decorsi sei mesi dall'inizio del rapporto di lavoro."},
    "l604_art6": {"norma": "art. 6 L. 604/1966", "titolo": "Articolo 6", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1966-07-15;604~art6", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Il licenziamento deve essere impugnato a pena di decadenza entro sessanta giorni dalla ricezione della sua comunicazione in forma scritta, ovvero dalla comunicazione, anch' essa in forma scritta, dei motivi, ove non contestuale, con qualsiasi atto scritto, anche extragiudiziale, idoneo a rendere nota la volonta' del lavoratore anche attraverso l'intervento dell'organizzazione sindacale diretto ad impugnare il […]"},
    "l633_art161": {"norma": "art. 161 L. 633/1941", "titolo": "Articolo 161", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1941-04-22;633~art161", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Agli effetti dell'esercizio delle azioni previste negli articoli precedenti, nonche' della salvaguardia delle prove relative alla contraffazione, possono essere ordinati dall'Autorita' giudiziaria la descrizione, l'accertamento, la perizia od il sequestro di cio' che si ritenga costituire violazione del diritto di utilizzazione; puo' inoltre farsi ricorso ai procedimenti d'istruzione preventiva. 2."},
    "l689_art22": {"norma": "art. 22 L. 689/1981", "titolo": "Opposizione all'ordinanza-ingiunzione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1981-11-24;689~art22", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Salvo quanto previsto dall'articolo 133 del decreto legislativo 2 luglio 2010, n. 104, e da altre disposizioni di legge, contro l'ordinanza-ingiunzione di pagamento e contro l'ordinanza che dispone la sola confisca gli interessati possono proporre opposizione dinanzi all'autorita' giudiziaria ordinaria. L'opposizione e' regolata dall'articolo 6 del decreto legislativo 1° settembre 2011, n. 150."},
    "l68_art7": {"norma": "art. 7 L. 68/1999", "titolo": "Modalita' delle assunzioni obbligatorie", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1999-03-12;68~art7", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Ai fini dell'adempimento dell'obbligo previsto dall'articolo 3, i datori di lavoro privati e gli enti pubblici economici assumono i lavoratori mediante richiesta nominativa di avviamento agli uffici competenti o mediante la stipula delle convenzioni di cui all'articolo 11."},
    "l898_art3": {"norma": "art. 3 L. 898/1970", "titolo": "Articolo 3", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1970-12-01;898~art3", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Lo scioglimento o la cessazione degli effetti civili del matrimonio puo' essere domandato da uno dei coniugi: 1) quando, dopo la celebrazione del matrimonio, l'altro coniuge e' stato condannato, con sentenza passata in giudicato, anche per fatti commessi in precedenza: a) all'ergastolo ovvero ad una pena superiore ad anni quindici, anche con piu' sentenze, per uno o piu' delitti non colposi, esclusi i reati politici […]"},
    "l89_art2": {"norma": "art. 2 L. 89/2001", "titolo": "Diritto all'equa riparazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2001-03-24;89~art2", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. E' inammissibile la domanda di equa riparazione proposta dal soggetto che non ha esperito i rimedi preventivi all'irragionevole durata del processo di cui all'articolo 1-ter. 2."},
    "l89_art3": {"norma": "art. 3 L. 89/2001", "titolo": "Procedimento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2001-03-24;89~art3", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La domanda di equa riparazione si propone con ricorso al presidente della corte d'appello del distretto in cui ha sede il giudice innanzi al quale si e' svolto il primo grado del processo presupposto. Si applica l'articolo 125 del codice di procedura civile 2."},
    "l89_art4": {"norma": "art. 4 L. 89/2001", "titolo": "Termine di proponibilita'", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2001-03-24;89~art4", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La domanda di riparazione puo' essere proposta, a pena di decadenza, entro sei mesi dal momento in cui la decisione che conclude il procedimento e' divenuta definitiva. In ogni caso la domanda puo' essere proposta in pendenza del processo quando e' superato il termine ragionevole di durata dello stesso."},
    "l89_art5ter": {"norma": "art. 5-ter L. 89/2001", "titolo": "Opposizione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:2001-03-24;89~art5ter", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Contro il decreto che ha deciso sulla domanda di equa riparazione puo' essere proposta opposizione nel termine perentorio di trenta giorni dalla comunicazione del provvedimento ovvero dalla sua notificazione. 2. L'opposizione si propone con ricorso davanti all'ufficio giudiziario al quale appartiene il giudice che ha emesso il decreto. Si applica l' articolo 125 del codice di procedura civile . 3."},
    "l91_art5": {"norma": "art. 5 L. 91/1992", "titolo": "Articolo 5", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1992-02-05;91~art5", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il coniuge, straniero o apolide, di cittadino italiano puo' acquistare la cittadinanza italiana quando, dopo il matrimonio, risieda legalmente da almeno due anni nel territorio della Repubblica, oppure dopo tre anni dalla data del matrimonio se residente all'estero, qualora, al momento dell'adozione del decreto di cui all'articolo 7, comma 1, non sia intervenuto lo scioglimento, l'annullamento o la cessazione […]"},
    "l91_art6": {"norma": "art. 6 L. 91/1992", "titolo": "Articolo 6", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1992-02-05;91~art6", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Precludono l'acquisto della cittadinanza ai sensi dell'articolo 5: a) la condanna per uno dei delitti previsti nel libro secondo, titolo I, capi I, II e III, del codice penale ; b) la condanna per un delitto non colposo per il quale la legge preveda una pena edittale non inferiore nel massimo a tre anni di reclusione; ovvero la condanna per un reato non politico ad una pena detentiva superiore ad un anno da parte […]"},
    "l91_art8": {"norma": "art. 8 L. 91/1992", "titolo": "Articolo 8", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1992-02-05;91~art8", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Con decreto motivato, il Ministro dell'interno respinge l'istanza di cui all'articolo 7 ove sussistano le cause ostative previste nell'articolo 6. Ove si tratti di ragioni inerenti alla sicurezza della Repubblica, il decreto e' emanato su conforme parere del Consiglio di Stato. L'istanza respinta puo' essere riproposta dopo cinque anni dall'emanazione del provvedimento. 2. COMMA ABROGATO DAL D.L."},
    "l91_art9": {"norma": "art. 9 L. 91/1992", "titolo": "Articolo 9", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1992-02-05;91~art9", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La cittadinanza italiana puo' essere concessa con decreto del Presidente della Repubblica, sentito il Consiglio di Stato, su proposta del Ministro dell'interno: a) allo straniero del quale il padre o la madre o uno degli ascendenti in linea retta di secondo grado sono o sono stati cittadini per nascita e che risiede legalmente nel territorio della Repubblica da almeno due anni , comunque fatto salvo quanto […]"},
    "l91_art9ter": {"norma": "art. 9-ter L. 91/1992", "titolo": "Articolo 9-ter", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:legge:1992-02-05;91~art9ter", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il termine di definizione dei procedimenti di cui agli articoli 5 e 9 e' fissato in ventiquattro mesi prorogabili fino al massimo di trentasei mesi dalla data di presentazione della domanda."},
    "lf_art98": {"norma": "art. 98 L.F.", "titolo": "Impugnazioni", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;267~art98", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Contro il decreto che rende esecutivo lo stato passivo puo' essere proposta opposizione, impugnazione dei crediti ammessi o revocazione. Con l'opposizione il creditore o il titolare di diritti su beni mobili o immobili contestano che la propria domanda sia stata accolta in parte o sia stata respinta; l'opposizione e' proposta nei confronti del curatore."},
    "lf_art99": {"norma": "art. 99 L.F.", "titolo": "Procedimento", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:regio.decreto:1942-03-16;267~art99", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Le impugnazioni di cui all'articolo precedente si propongono con ricorso depositato presso la cancelleria del tribunale entro trenta giorni dalla comunicazione di cui all'articolo 97 ovvero in caso di revocazione dalla scoperta del fatto o del documento."},
    "privacy_art140bis": {"norma": "art. 140-bis D.Lgs. 196/2003", "titolo": "Forme alternative di tutela", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2003-06-30;196~art140bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Qualora ritenga che i diritti di cui gode sulla base della normativa in materia di protezione dei dati personali siano stati violati, l'interessato puo' proporre reclamo al Garante o ricorso dinanzi all'autorita' giudiziaria. 2. Il reclamo al Garante non puo' essere proposto se, per il medesimo oggetto e tra le stesse parti, e' stata gia' adita l'autorita' giudiziaria. 3."},
    "privacy_art142": {"norma": "art. 142 D.Lgs. 196/2003", "titolo": "Proposizione del reclamo", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2003-06-30;196~art142", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il reclamo contiene un'indicazione per quanto possibile dettagliata dei fatti e delle circostanze su cui si fonda, delle disposizioni che si presumono violate e delle misure richieste, nonche' gli estremi identificativi del titolare o del responsabile del trattamento, ove conosciuto. 2."},
    "privacy_art143": {"norma": "art. 143 D.Lgs. 196/2003", "titolo": "Decisione del reclamo", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2003-06-30;196~art143", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Esaurita l'istruttoria preliminare, se il reclamo non e' manifestamente infondato e sussistono i presupposti per adottare un provvedimento, il Garante, anche prima della definizione del procedimento puo' adottare i provvedimenti di cui all'articolo 58 del Regolamento nel rispetto delle disposizioni di cui all'articolo 56 dello stesso. 2."},
    "privacy_art152": {"norma": "art. 152 D.Lgs. 196/2003", "titolo": "Autorita' giudiziaria ordinaria", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2003-06-30;196~art152", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Tutte le controversie che riguardano le materie oggetto dei ricorsi giurisdizionali di cui agli articoli 78 e 79 del Regolamento e quelli comunque riguardanti l'applicazione della normativa in materia di protezione dei dati personali, nonche' il diritto al risarcimento del danno ai sensi dell'articolo 82 del medesimo regolamento, sono attribuite all'autorita' giudiziaria ordinaria. 1-bis."},
    "tu175_art100": {"norma": "art. 100 D.Lgs. 175/2024", "titolo": "Conciliazione in udienza", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2024-11-14;175~art100", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Ciascuna parte entro il termine di cui all'articolo 80, comma 2, può presentare istanza per la conciliazione totale o parziale della controversia. 2. All'udienza la corte di giustizia tributaria, se sussistono le condizioni di ammissibilità, invita le parti alla conciliazione rinviando eventualmente la causa alla successiva udienza per il perfezionamento dell'accordo conciliativo. 3."},
    "tu175_art106": {"norma": "art. 106 D.Lgs. 175/2024", "titolo": "Giudice competente e provvedimenti sull'esecuzione provvisoria in appello", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2024-11-14;175~art106", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La sentenza della corte di giustizia tributaria di primo grado può essere appellata alla corte di giustizia tributaria di secondo grado competente a norma dell'articolo 48, comma 2. 2. L'appellante può chiedere alla corte di giustizia tributaria di secondo grado di sospendere in tutto o in parte l'esecutività della sentenza impugnata, se sussistono gravi e fondati motivi. 3."},
    "tu175_art107": {"norma": "art. 107 D.Lgs. 175/2024", "titolo": "Forma dell'appello", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2024-11-14;175~art107", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorso in appello contiene l'indicazione della corte di giustizia tributaria di secondo grado a cui è diretto, dell'appellante e delle altre parti nei cui confronti è proposto, gli estremi della sentenza impugnata, l'esposizione sommaria dei fatti, l'oggetto della domanda ed i motivi specifici dell'impugnazione."},
    "tu175_art116": {"norma": "art. 116 D.Lgs. 175/2024", "titolo": "Norme applicabili", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2024-11-14;175~art116", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Avverso la sentenza della corte di giustizia tributaria di secondo grado può essere proposto ricorso per cassazione per i motivi di cui ai numeri da 1 a 5 dell'articolo 360, primo comma, del codice di procedura civile. 2. Al ricorso per cassazione ed al relativo procedimento si applicano le norme dettate dal codice di procedura civile in quanto compatibili con quelle del presente testo unico. 3."},
    "tu175_art128": {"norma": "art. 128 D.Lgs. 175/2024", "titolo": "Giudizio di ottemperanza", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2024-11-14;175~art128", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. La parte che vi ha interesse può richiedere l'ottemperanza agli obblighi derivanti dalla sentenza della corte di giustizia tributaria di primo e secondo grado mediante ricorso da depositare in doppio originale alla segreteria della corte di giustizia tributaria di primo grado, qualora la sentenza sia stata da essa pronunciata, e in ogni altro caso alla segreteria della corte di giustizia tributaria di secondo […]"},
    "tu175_art131": {"norma": "art. 131 D.Lgs. 175/2024", "titolo": "Decorrenza", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2024-11-14;175~art131", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "Art. 131 D.Lgs. 175/2024 (Decorrenza), testo integrale: 1. Le disposizioni del presente testo unico si applicano dal 1° gennaio 2027."},
    "tu175_art65": {"norma": "art. 65 D.Lgs. 175/2024", "titolo": "Atti impugnabili e oggetto del ricorso", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2024-11-14;175~art65", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorso può essere proposto avverso: a) l'avviso di accertamento del tributo; b) l'avviso di liquidazione del tributo; c) il provvedimento che irroga le sanzioni; d) il ruolo e la cartella di pagamento; e) l'avviso di mora; f) l'iscrizione di ipoteca sugli immobili di cui all'articolo 178 del testo unico in materia di versamenti e di riscossione di cui al decreto legislativo 24 marzo 2025, n."},
    "tu175_art96": {"norma": "art. 96 D.Lgs. 175/2024", "titolo": "Sospensione dell'atto impugnato", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2024-11-14;175~art96", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il ricorrente, se dall'atto impugnato può derivargli un danno grave ed irreparabile, può chiedere alla corte di giustizia tributaria di primo o di secondo grado presso la quale è pendente il giudizio, ovvero adita ai sensi dell'articolo 117 la sospensione dell'esecuzione dell'atto stesso con istanza motivata proposta nel ricorso o con atto separato notificata alle altre parti e depositato in segreteria sempre che […]"},
    "tu175_art99": {"norma": "art. 99 D.Lgs. 175/2024", "titolo": "Conciliazione fuori udienza", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2024-11-14;175~art99", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Se in pendenza del giudizio le parti raggiungono un accordo conciliativo, presentano istanza congiunta sottoscritta personalmente o dai difensori per la definizione totale o parziale della controversia. 2. Se la data di trattazione è già fissata e sussistono le condizioni di ammissibilità, la corte di giustizia tributaria pronuncia sentenza di cessazione della materia del contendere."},
    "tuimm_art13": {"norma": "art. 13 D.Lgs. 286/1998", "titolo": "Espulsione amministrativa", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1998-07-25;286~art13", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Per motivi di ordine pubblico o di sicurezza dello Stato, il Ministro dell'interno puo' disporre l'espulsione dello straniero anche non residente nel territorio dello Stato, dandone preventiva notizia al Presidente del Consiglio dei ministri e al Ministro degli affari esteri. 2."},
    "tuimm_art14": {"norma": "art. 14 D.Lgs. 286/1998", "titolo": "Esecuzione dell'espulsione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1998-07-25;286~art14", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Quando non e' possibile eseguire con immediatezza l'espulsione mediante accompagnamento alla frontiera o il respingimento, a causa di situazioni transitorie che ostacolano la preparazione del rimpatrio o l'effettuazione dell'allontanamento, il questore dispone che lo straniero sia trattenuto per il tempo strettamente necessario presso il centro di permanenza per i rimpatri piu' vicino, tra quelli individuati o […]"},
    "tuimm_art29": {"norma": "art. 29 D.Lgs. 286/1998", "titolo": "Ricongiungimento familiare", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1998-07-25;286~art29", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Lo straniero puo' chiedere il ricongiungimento per i seguenti familiari: a) coniuge non legalmente separato e di eta' non inferiore ai diciotto anni; b) figli minori, anche del coniuge o nati fuori del matrimonio, non coniugati, a condizione che l'altro genitore, qualora esistente, abbia dato il suo consenso; c) figli maggiorenni a carico, qualora per ragioni oggettive non possano provvedere alle proprie […]"},
    "tuimm_art30": {"norma": "art. 30 D.Lgs. 286/1998", "titolo": "Permesso di soggiorno per motivi familiari", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1998-07-25;286~art30", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Fatti salvi i casi di rilascio o di rinnovo della carta di soggiorno, il permesso di soggiorno per motivi familiari e' rilasciato: a) allo straniero che ha fatto ingresso in Italia con visto di ingresso per ricongiungimento familiare, ovvero con visto di ingresso al seguito del proprio familiare nei casi previsti dall'articolo 29, ovvero con visto di ingresso per ricongiungimento al figlio minore; b) agli […]"},
    "tuimm_art44": {"norma": "art. 44 D.Lgs. 286/1998", "titolo": "Azione civile contro la discriminazione", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1998-07-25;286~art44", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Quando il comportamento di un privato o della pubblica amministrazione produce una discriminazione per motivi razziali, etnici, linguistici, nazionali, di provenienza geografica o religiosi, e' possibile ricorrere all'autorita' giudiziaria ordinaria per domandare la cessazione del comportamento pregiudizievole e la rimozione degli effetti della discriminazione. 2."},
    "tupi_art30": {"norma": "art. 30 D.Lgs. 165/2001", "titolo": "Passaggio diretto di personale tra amministrazioni diverse", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2001-03-30;165~art30", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le amministrazioni possono ricoprire posti vacanti in organico mediante passaggio diretto di dipendenti di cui all'articolo 2, comma 2, appartenenti a una qualifica corrispondente e in servizio presso altre amministrazioni, che facciano domanda di trasferimento."},
    "tupi_art31": {"norma": "art. 31 D.Lgs. 165/2001", "titolo": "Passaggio di dipendenti per effetto di trasferimento di attivita'", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2001-03-30;165~art31", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Fatte salve le disposizioni speciali, nel caso di trasferimento o conferimento di attivita', svolte da pubbliche amministrazioni, enti pubblici o loro aziende o strutture, ad altri soggetti, pubblici o privati, al personale che passa alle dipendenze ditali soggetti si applicano l' articolo 2112 del codice civile e si osservano le procedure di informazione e di consultazione di cui all' articolo 47, commi da 1 a […]"},
    "tupi_art33": {"norma": "art. 33 D.Lgs. 165/2001", "titolo": "Eccedenze di personale e mobilita' collettiva", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2001-03-30;165~art33", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le pubbliche amministrazioni che hanno situazioni di soprannumero o rilevino comunque eccedenze di personale, in relazione alle esigenze funzionali o alla situazione finanziaria, anche in sede di ricognizione annuale prevista dall'articolo 6, comma 1, terzo e quarto periodo, sono tenute ad osservare le procedure previste dal presente articolo dandone immediata comunicazione al Dipartimento della funzione […]"},
    "tupi_art34": {"norma": "art. 34 D.Lgs. 165/2001", "titolo": "Gestione del personale in disponibilita'", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2001-03-30;165~art34", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il personale in disponibilita' e' iscritto in appositi elenchi secondo l'ordine cronologico di sospensione del relativo rapporto di lavoro. 2. Per le amministrazioni dello Stato, anche ad ordinamento autonomo e per gli enti pubblici non economici nazionali, il Dipartimento della funzione pubblica della Presidenza del Consiglio dei ministri forma e gestisce l'elenco, avvalendosi anche, ai fini della […]"},
    "tupi_art35": {"norma": "art. 35 D.Lgs. 165/2001", "titolo": "Articolo 35", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2001-03-30;165~art35", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. L'assunzione nelle amministrazioni pubbliche avviene con contratto individuale di lavoro: a) tramite procedure selettive, conformi ai principi del comma 3, volte all'accertamento della professionalita' richiesta, che garantiscano in misura adeguata l'accesso dall'esterno; b) mediante avviamento degli iscritti nelle liste di collocamento ai sensi della legislazione vigente per le qualifiche e profili per i quali […]"},
    "tupi_art36": {"norma": "art. 36 D.Lgs. 165/2001", "titolo": "Personale a tempo determinato o assunto con forme di lavoro flessibile", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2001-03-30;165~art36", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Per le esigenze connesse con il proprio fabbisogno ordinario le pubbliche amministrazioni assumono esclusivamente con contratti di lavoro subordinato a tempo indeterminato seguendo le procedure di reclutamento previste dall'articolo 35. 2."},
    "tupi_art52": {"norma": "art. 52 D.Lgs. 165/2001", "titolo": "Disciplina delle mansioni", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2001-03-30;165~art52", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Il prestatore di lavoro deve essere adibito alle mansioni per le quali e' stato assunto o alle mansioni equivalenti nell'ambito dell'area di inquadramentoovvero a quelle corrispondenti alla qualifica superiore che abbia successivamente acquisito per effetto delle procedure selettive di cui all'articolo 35, comma 1, lettera a)."},
    "tupi_art55": {"norma": "art. 55 D.Lgs. 165/2001", "titolo": "Responsabilita', infrazioni e sanzioni, procedure conciliative", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2001-03-30;165~art55", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Le disposizioni del presente articolo e di quelli seguenti, fino all'articolo 55-octies, costituiscono norme imperative, ai sensi e per gli effetti degli articoli 1339 e 1419, secondo comma, del codice civile , e si applicano ai rapporti di lavoro di cui all'articolo 2, comma 2, alle dipendenze delle amministrazioni pubbliche di cui all'articolo 1, comma 2."},
    "tupi_art55bis": {"norma": "art. 55-bis D.Lgs. 165/2001", "titolo": "Forme e termini del procedimento disciplinare", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2001-03-30;165~art55bis", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Per le infrazioni di minore gravita', per le quali e' prevista l'irrogazione della sanzione del rimprovero verbale, il procedimento disciplinare e' di competenza del responsabile della struttura presso cui presta servizio il dipendente. Alle infrazioni per le quali e' previsto il rimprovero verbale si applica la disciplina stabilita dal contratto collettivo. 2."},
    "tupi_art55quater": {"norma": "art. 55-quater D.Lgs. 165/2001", "titolo": "Licenziamento disciplinare", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2001-03-30;165~art55quater", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Ferma la disciplina in tema di licenziamento per giusta causa o per giustificato motivo e salve ulteriori ipotesi previste dal contratto collettivo, si applica comunque la sanzione disciplinare del licenziamento nei seguenti casi: a) falsa attestazione della presenza in servizio, mediante l'alterazione dei sistemi di rilevamento della presenza o con altre modalita' fraudolente, ovvero giustificazione dell'assenza […]"},
    "tupi_art64": {"norma": "art. 64 D.Lgs. 165/2001", "titolo": "Accertamento pregiudiziale sull'efficacia, validita' ed interpretazione dei contratto collettivi", "url": "https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:2001-03-30;165~art64", "verifica": "testo vigente letto dall'archivio Normattiva del software il 06/11/2026", "estratto": "1. Quando per la definizione di una controversia individuale di cui all'articolo 63, e' necessario risolvere in via pregiudiziale una questione concernente l'efficacia, la validita' o l'interpretazione delle clausole di un contratto o accordo collettivo nazionale, sottoscritto dall'ARAN ai sensi dell'articolo 40 e seguenti, il giudice, con ordinanza non impugnabile, nella quale indica la questione da risolvere, […]"},
}
